insert into public.translations (locale, key, value) values
  ('pt-BR', 'docs.adaptiveRouting.title', $json$"Roteamento adaptativo"$json$::jsonb),
  ('pt-BR', 'docs.adaptiveRouting.summary', $json$"O Jev escolhe qual agente e qual modelo respondem a cada pedido, pesando o histórico de cada modelo por tipo de pedido."$json$::jsonb),
  ('pt-BR', 'docs.adaptiveRouting.usage', $json$"Deixe mais de um agente ligado na Configuração. Uma resposta que você diz que não funcionou, ou que a portaria de saída segura, custa um ponto ao modelo. Se o agente escolhido não estiver instalado ou sem login, o pedido vai para o próximo."$json$::jsonb),
  ('pt-BR', 'docs.agentSessions.title', $json$"Sessões do agente"$json$::jsonb),
  ('pt-BR', 'docs.agentSessions.summary', $json$"Cada chat retoma a sessão do seu agente em vez de reler o projeto e a conversa inteira a cada mensagem."$json$::jsonb),
  ('pt-BR', 'docs.agentSessions.usage', $json$"Sempre ligado. Uma sessão nova começa depois de 10 pedidos, ou quando o agente, o modelo ou a pasta mudam."$json$::jsonb),
  ('pt-BR', 'docs.agents.title', $json$"Agentes de linha de comando"$json$::jsonb),
  ('pt-BR', 'docs.agents.summary', $json$"O JayV não escreve código sozinho: ele orquestra os agentes de código que você já usa — Codex, Claude Code, GitHub Copilot e Cursor Agent — rodando a linha de comando de cada um no seu computador."$json$::jsonb),
  ('pt-BR', 'docs.agents.usage', $json$"Abra a Configuração, ligue os agentes instalados neste computador e liste os modelos que cada um pode usar. Cada CLI mantém o próprio login; nenhuma chave ou senha passa pelo JayV. A página Sistema mostra se cada agente está instalado e respondendo."$json$::jsonb),
  ('pt-BR', 'docs.answerRecall.title', $json$"Respostas anteriores"$json$::jsonb),
  ('pt-BR', 'docs.answerRecall.summary', $json$"Um pedido quase igual a outro já respondido em outro chat do mesmo projeto começa daquela resposta, em vez de explorar tudo de novo."$json$::jsonb),
  ('pt-BR', 'docs.answerRecall.usage', $json$"Funciona sozinho quando o seu plano inclui. Cada vez que uma resposta anterior é reaproveitada, o painel do Jev mostra."$json$::jsonb),
  ('pt-BR', 'docs.chatSearch.title', $json$"Busca nos chats"$json$::jsonb),
  ('pt-BR', 'docs.chatSearch.summary', $json$"Busque palavras em todas as conversas de um projeto, com o trecho encontrado destacado."$json$::jsonb),
  ('pt-BR', 'docs.chatSearch.usage', $json$"Na tela de chats de um projeto, digite no campo de busca. O índice fica no seu computador e a busca nunca vai para a rede."$json$::jsonb),
  ('pt-BR', 'docs.cli.title', $json$"O JayV no terminal"$json$::jsonb),
  ('pt-BR', 'docs.cli.summary', $json$"O mesmo orquestrador roda num terminal, com os agentes e modelos configurados no app."$json$::jsonb),
  ('pt-BR', 'docs.cli.usage', $json$"Rode jayv seguido de um comando na pasta do projeto, ou passe a pasta com --root. --config aponta para outro arquivo de configuração."$json$::jsonb),
  ('pt-BR', 'docs.commandPalette.title', $json$"Paleta de comandos e atalhos"$json$::jsonb),
  ('pt-BR', 'docs.commandPalette.summary', $json$"Tudo que tem botão também tem nome na paleta de comandos, e as telas principais têm atalhos de teclado."$json$::jsonb),
  ('pt-BR', 'docs.commandPalette.usage', $json$"Pressione Ctrl+K (⌘K no Mac) em qualquer tela e digite: ir para uma página, abrir um projeto, chat ou organização, começar um chat ou trocar o tema."$json$::jsonb),
  ('pt-BR', 'docs.contextCache.title', $json$"Cache de contexto"$json$::jsonb),
  ('pt-BR', 'docs.contextCache.summary', $json$"O contexto montado para um pedido é reaproveitado por pelo menos cinco minutos enquanto os arquivos não mudam, então o pedido seguinte não busca no projeto de novo."$json$::jsonb),
  ('pt-BR', 'docs.contextCache.usage', $json$"Sempre ligado. Mudar um arquivo do projeto atualiza só o que mudou."$json$::jsonb),
  ('pt-BR', 'docs.entryGate.title', $json$"Portaria de entrada"$json$::jsonb),
  ('pt-BR', 'docs.entryGate.summary', $json$"O Jev confere cada pedido antes de qualquer agente rodar: o que ele pede, onde se aplica e o que está faltando."$json$::jsonb),
  ('pt-BR', 'docs.entryGate.usage', $json$"Sempre ligada. Quando falta algo, a portaria mostra e oferece enviar como está, enviar a versão que o JayV reescreveu ou completar o pedido."$json$::jsonb),
  ('pt-BR', 'docs.exitGate.title', $json$"Portaria de saída"$json$::jsonb),
  ('pt-BR', 'docs.exitGate.summary', $json$"O Jev confere os comandos e arquivos de cada resposta contra as regras do projeto antes de você agir sobre ela."$json$::jsonb),
  ('pt-BR', 'docs.exitGate.usage', $json$"Sempre ligada. Uma resposta que mexe num arquivo protegido ou roda um comando proibido fica segurada, e a portaria explica por quê."$json$::jsonb),
  ('pt-BR', 'docs.gateBoard.title', $json$"Painel da portaria"$json$::jsonb),
  ('pt-BR', 'docs.gateBoard.summary', $json$"Uma página com tudo que o Jev deixou passar, perguntou ou barrou no projeto."$json$::jsonb),
  ('pt-BR', 'docs.gateBoard.usage', $json$"Abra pelo menu lateral, pela contagem na barra de status ou com Ctrl+G (⌘G no Mac). As respostas que você dá à portaria viram notas do projeto, e ela não pergunta de novo."$json$::jsonb),
  ('pt-BR', 'docs.leanCode.title', $json$"Código enxuto"$json$::jsonb),
  ('pt-BR', 'docs.leanCode.summary', $json$"No modo de desenvolvimento, o agente escreve o mínimo de código que resolve a tarefa e reaproveita o que a linguagem, a plataforma ou uma biblioteca instalada já fazem."$json$::jsonb),
  ('pt-BR', 'docs.leanCode.usage', $json$"Ligado por padrão. Validação, tratamento de erros, segurança e acessibilidade nunca são cortados. Desligue em Seu nível, na página Perfil."$json$::jsonb),
  ('pt-BR', 'docs.liveFiles.title', $json$"Arquivos ao vivo"$json$::jsonb),
  ('pt-BR', 'docs.liveFiles.summary', $json$"Um painel ao lado da conversa mostra cada arquivo que o pedido altera, do mais recente para o mais antigo, com o diff de cada um enquanto o agente escreve."$json$::jsonb),
  ('pt-BR', 'docs.liveFiles.usage', $json$"Clique em Ao vivo no cabeçalho do chat; ele também abre sozinho na primeira mudança. Siga o agente para ver cada arquivo assim que ele muda."$json$::jsonb),
  ('pt-BR', 'docs.orgChat.title', $json$"Chat da organização"$json$::jsonb),
  ('pt-BR', 'docs.orgChat.summary', $json$"Um chat que trabalha em todos os repositórios de uma organização de uma vez, com o agente, o índice e a portaria enxergando todos eles."$json$::jsonb),
  ('pt-BR', 'docs.orgChat.usage', $json$"Na página da organização, clique em Chat da organização. Sem uma pasta da organização neste computador, o JayV pede uma antes."$json$::jsonb),
  ('pt-BR', 'docs.organizations.title', $json$"Organizações"$json$::jsonb),
  ('pt-BR', 'docs.organizations.summary', $json$"As organizações reúnem pessoas, repositórios e a política de LLM que o time inteiro segue."$json$::jsonb),
  ('pt-BR', 'docs.organizations.usage', $json$"Crie uma organização e convide membros no painel do site do JayV. No app, Ctrl+2 (⌘2 no Mac) abre as suas organizações e os repositórios delas."$json$::jsonb),
  ('pt-BR', 'docs.parallelRequests.title', $json$"Pedidos em paralelo"$json$::jsonb),
  ('pt-BR', 'docs.parallelRequests.summary', $json$"Quando o seu plano permite mais de um pedido ao mesmo tempo, chats de projetos diferentes rodam juntos, cada um com os seus agentes e o seu índice."$json$::jsonb),
  ('pt-BR', 'docs.parallelRequests.usage', $json$"Não há nada para ligar: envie pedidos em chats de projetos diferentes e eles não esperam mais um pelo outro. Pedidos do mesmo projeto continuam um de cada vez, para dois agentes nunca escreverem na mesma pasta."$json$::jsonb),
  ('pt-BR', 'docs.parallelTasks.title', $json$"Agentes em paralelo"$json$::jsonb),
  ('pt-BR', 'docs.parallelTasks.summary', $json$"Um pedido grande de desenvolvimento num projeto git é dividido em até quatro partes que mexem em arquivos separados, cada uma feita por um agente diferente na sua própria cópia do projeto."$json$::jsonb),
  ('pt-BR', 'docs.parallelTasks.usage', $json$"Ligue Dividir pedidos grandes entre agentes em Configuração › Jev › Roteamento. As partes rodam ao mesmo tempo em git worktrees e as mudanças voltam para a sua pasta."$json$::jsonb),
  ('pt-BR', 'docs.planFirst.title', $json$"Planejar antes de construir"$json$::jsonb),
  ('pt-BR', 'docs.planFirst.summary', $json$"Num pedido de desenvolvimento complexo, o seu modelo de raciocínio mais forte escreve um plano primeiro, e o agente escolhido para construir o recebe junto do pedido."$json$::jsonb),
  ('pt-BR', 'docs.planFirst.usage', $json$"Ligue Planejar com um modelo, construir com outro em Configuração › Jev › Roteamento. O plano aparece no painel de andamento enquanto é escrito; se ele falhar, o desenvolvimento segue como antes."$json$::jsonb),
  ('pt-BR', 'docs.profilePhoto.title', $json$"Foto de perfil"$json$::jsonb),
  ('pt-BR', 'docs.profilePhoto.summary', $json$"A sua própria foto, mostrada no JayV seja qual for a forma de login — e-mail e senha ou qualquer conta vinculada."$json$::jsonb),
  ('pt-BR', 'docs.profilePhoto.usage', $json$"No site do JayV, abra Painel › Conta, clique na foto, escolha uma imagem e ajuste o recorte. O app a mostra na próxima vez que abrir; removê-la traz de volta a foto da conta vinculada."$json$::jsonb),
  ('pt-BR', 'docs.progressPanel.title', $json$"Painel de andamento"$json$::jsonb),
  ('pt-BR', 'docs.progressPanel.summary', $json$"Um painel ao lado do menu lateral mostra o que o JayV está fazendo agora, um passo por linha, para a conversa ficar com a largura inteira."$json$::jsonb),
  ('pt-BR', 'docs.progressPanel.usage', $json$"O painel abre sozinho enquanto um pedido roda. Recolha-o numa faixa fina quando não precisar; num chat da organização ele também lista os repositórios."$json$::jsonb),
  ('pt-BR', 'docs.projectNotes.title', $json$"Memória do projeto"$json$::jsonb),
  ('pt-BR', 'docs.projectNotes.summary', $json$"Notas curtas sobre o projeto — como testar, onde as coisas ficam, o que não mexer — que o agente recebe uma vez, no começo de cada sessão."$json$::jsonb),
  ('pt-BR', 'docs.projectNotes.usage', $json$"Na tela de chats de um projeto, clique em Memória do projeto e escreva até 2.200 caracteres. Segredos são recusados, e as notas sincronizam com a sua conta."$json$::jsonb),
  ('pt-BR', 'docs.secondOpinion.title', $json$"Segunda opinião"$json$::jsonb),
  ('pt-BR', 'docs.secondOpinion.summary', $json$"Depois que um pedido muda o projeto no modo de desenvolvimento, um agente de outro provedor lê o diff sem editar nada e lista os problemas que encontrar."$json$::jsonb),
  ('pt-BR', 'docs.secondOpinion.usage', $json$"Ligue Segunda opinião de outro agente em Configuração › Jev › Roteamento. Precisa de pelo menos dois agentes ligados; a resposta chega primeiro e a revisão vem em seguida, numa mensagem própria."$json$::jsonb),
  ('pt-BR', 'docs.secretRedaction.title', $json$"Ocultação de segredos"$json$::jsonb),
  ('pt-BR', 'docs.secretRedaction.summary', $json$"Chaves, tokens e senhas são substituídos antes de qualquer arquivo chegar a um modelo."$json$::jsonb),
  ('pt-BR', 'docs.secretRedaction.usage', $json$"Sempre ligada, em todo plano; não há chave para desligar."$json$::jsonb),
  ('pt-BR', 'docs.sensitiveFiles.title', $json$"Arquivos protegidos"$json$::jsonb),
  ('pt-BR', 'docs.sensitiveFiles.summary', $json$"Arquivos como .env, chaves privadas e certificados nunca entram no contexto, e os agentes não podem lê-los nem editá-los."$json$::jsonb),
  ('pt-BR', 'docs.sensitiveFiles.usage', $json$"A lista padrão vale sempre; acrescente os seus padrões em Nunca ler, em Configuração › Aplicativo. O Claude Code também bloqueia as próprias leituras e edições desses arquivos, e qualquer mudança de um agente num arquivo protegido fica segurada na portaria de saída."$json$::jsonb),
  ('pt-BR', 'docs.stats.title', $json$"Estatísticas"$json$::jsonb),
  ('pt-BR', 'docs.stats.summary', $json$"Uso de tokens, custo, cotas dos agentes e gráficos por projeto e por organização."$json$::jsonb),
  ('pt-BR', 'docs.stats.usage', $json$"Abra Estatísticas pelo menu lateral ou pressione Ctrl+3 (⌘3 no Mac)."$json$::jsonb),
  ('pt-BR', 'docs.stopRequest.title', $json$"Parar um pedido"$json$::jsonb),
  ('pt-BR', 'docs.stopRequest.summary', $json$"Um pedido em andamento pode ser parado a qualquer momento: o agente e todos os processos que ele abriu são fechados, e o que ele já disse fica no chat."$json$::jsonb),
  ('pt-BR', 'docs.stopRequest.usage', $json$"Enquanto um pedido roda, o botão Enviar vira Parar. Um pedido esperando na fila pode ser tirado dela. Todo pedido também para no tempo-limite definido em Configuração › Jev (30 minutos por padrão)."$json$::jsonb),
  ('pt-BR', 'docs.symbolIndex.title', $json$"Índice de símbolos para o Claude"$json$::jsonb),
  ('pt-BR', 'docs.symbolIndex.summary', $json$"O JayV mapeia onde cada função, tipo e classe é definido, no seu computador e sem gastar tokens, e o Claude Code pode consultar esse mapa em vez de varrer a pasta."$json$::jsonb),
  ('pt-BR', 'docs.symbolIndex.usage', $json$"Ligue Ferramentas de símbolos do JayV nas opções do Claude Code, na Configuração, quando o seu plano incluir. O mesmo índice é servido para qualquer agente pelo comando jayv mcp."$json$::jsonb),
  ('pt-BR', 'docs.twoFactor.title', $json$"Autenticação de dois fatores"$json$::jsonb),
  ('pt-BR', 'docs.twoFactor.summary', $json$"Além da senha ou da conta vinculada, entrar pede um código de um app autenticador no seu celular."$json$::jsonb),
  ('pt-BR', 'docs.twoFactor.usage', $json$"No site do JayV, abra Painel › Conta › Segurança, leia o QR code com um app autenticador e confirme com o primeiro código."$json$::jsonb),
  ('pt-BR', 'docs.updates.title', $json$"Atualizações e novidades"$json$::jsonb),
  ('pt-BR', 'docs.updates.summary', $json$"O JayV procura uma versão nova em segundo plano e, depois de cada atualização, mostra o que mudou desde a última versão que você viu."$json$::jsonb),
  ('pt-BR', 'docs.updates.usage', $json$"Quando sai uma versão nova, uma barra oferece O que muda e Atualizar agora. O histórico completo está em Novidades do JayV, na paleta de comandos, e na página Notas da versão do site."$json$::jsonb),
  ('pt-BR', 'docs.workModes.title', $json$"Modos de trabalho: Auto, Planejamento e Desenvolvimento"$json$::jsonb),
  ('pt-BR', 'docs.workModes.summary', $json$"Cada chat tem um modo de trabalho. Planejamento só lê o projeto e responde com um plano; Desenvolvimento muda arquivos; Auto deixa o Jev escolher a cada pedido."$json$::jsonb),
  ('pt-BR', 'docs.workModes.usage', $json$"Escolha o modo embaixo da caixa de mensagem, digite /plan, /build ou /auto no começo de uma mensagem, ou pressione Ctrl+. (⌘. no Mac). Quando um chat em Planejamento pede para implementar, o Jev o passa para Desenvolvimento."$json$::jsonb),
  ('pt-BR', 'docs.command.modeAuto', $json$"O Jev escolhe planejamento ou desenvolvimento para cada pedido deste chat."$json$::jsonb),
  ('pt-BR', 'docs.command.modePlan', $json$"Põe o chat em Planejamento: o agente só lê e responde com um plano. O texto depois do comando vai como o pedido."$json$::jsonb),
  ('pt-BR', 'docs.command.modeBuild', $json$"Põe o chat em Desenvolvimento: o agente muda arquivos do projeto. O texto depois do comando vai como o pedido."$json$::jsonb),
  ('pt-BR', 'docs.command.palette', $json$"Abre a paleta de comandos."$json$::jsonb),
  ('pt-BR', 'docs.command.projects', $json$"Vai para Projetos."$json$::jsonb),
  ('pt-BR', 'docs.command.organizations', $json$"Vai para Organizações."$json$::jsonb),
  ('pt-BR', 'docs.command.stats', $json$"Vai para Estatísticas."$json$::jsonb),
  ('pt-BR', 'docs.command.system', $json$"Vai para Sistema."$json$::jsonb),
  ('pt-BR', 'docs.command.settings', $json$"Abre a Configuração."$json$::jsonb),
  ('pt-BR', 'docs.command.newChat', $json$"Começa um chat novo no projeto aberto."$json$::jsonb),
  ('pt-BR', 'docs.command.gate', $json$"Abre a portaria do projeto aberto."$json$::jsonb),
  ('pt-BR', 'docs.command.workMode', $json$"Troca o modo de trabalho do chat aberto."$json$::jsonb),
  ('pt-BR', 'docs.command.cliStatus', $json$"Mostra a versão, o arquivo de configuração, quantos agentes e modelos podem rodar e quantos arquivos estão indexados."$json$::jsonb),
  ('pt-BR', 'docs.command.cliRun', $json$"Envia um pedido pela portaria e pelo roteador e imprime a resposta."$json$::jsonb),
  ('pt-BR', 'docs.command.cliIndex', $json$"Indexa a pasta do projeto e imprime quantos arquivos entraram."$json$::jsonb),
  ('pt-BR', 'docs.command.cliVersion', $json$"Imprime a versão instalada."$json$::jsonb),
  ('pt-BR', 'docs.command.cliBench', $json$"Roda um arquivo de tarefas pelo JayV e direto no agente, cada um na sua própria cópia, e compara rodadas e custo."$json$::jsonb),
  ('pt-BR', 'docs.command.cliMcp', $json$"Serve o índice de símbolos do projeto por MCP (stdio) para agentes de código."$json$::jsonb),
  ('en', 'docs.adaptiveRouting.title', $json$"Adaptive routing"$json$::jsonb),
  ('en', 'docs.adaptiveRouting.summary', $json$"Jev picks which agent and model answer each request, weighing each model's track record per kind of request."$json$::jsonb),
  ('en', 'docs.adaptiveRouting.usage', $json$"Keep more than one agent enabled in Settings. An answer you report as not working, or that the exit gate holds, costs the model a point. If the chosen agent is missing or not logged in, the request goes to the next one."$json$::jsonb),
  ('en', 'docs.agentSessions.title', $json$"Agent sessions"$json$::jsonb),
  ('en', 'docs.agentSessions.summary', $json$"Each chat resumes its agent's session instead of re-reading the project and the whole conversation on every message."$json$::jsonb),
  ('en', 'docs.agentSessions.usage', $json$"Always on. A new session starts after 10 requests, or when the agent, the model or the folder changes."$json$::jsonb),
  ('en', 'docs.agents.title', $json$"Command-line agents"$json$::jsonb),
  ('en', 'docs.agents.summary', $json$"JayV does not write code by itself: it orchestrates the coding agents you already use — Codex, Claude Code, GitHub Copilot and Cursor Agent — running each one's own command line on your computer."$json$::jsonb),
  ('en', 'docs.agents.usage', $json$"Open Settings, turn on the agents installed on this computer and list the models each one may use. Each CLI keeps its own login; no key or password passes through JayV. The System page shows whether each agent is installed and answering."$json$::jsonb),
  ('en', 'docs.answerRecall.title', $json$"Earlier answers"$json$::jsonb),
  ('en', 'docs.answerRecall.summary', $json$"A request almost identical to one already answered in another chat of the same project starts from that answer instead of exploring everything again."$json$::jsonb),
  ('en', 'docs.answerRecall.usage', $json$"It works on its own when your plan includes it. Each time an earlier answer is reused, the Jev panel shows it."$json$::jsonb),
  ('en', 'docs.chatSearch.title', $json$"Chat search"$json$::jsonb),
  ('en', 'docs.chatSearch.summary', $json$"Search for words across every conversation of a project, with the matching passage highlighted."$json$::jsonb),
  ('en', 'docs.chatSearch.usage', $json$"On a project's chats screen, type in the search field. The index lives on your computer and the search never goes to the network."$json$::jsonb),
  ('en', 'docs.cli.title', $json$"JayV on the terminal"$json$::jsonb),
  ('en', 'docs.cli.summary', $json$"The same orchestrator runs from a terminal, with the agents and models configured in the app."$json$::jsonb),
  ('en', 'docs.cli.usage', $json$"Run jayv followed by a command in the project folder, or pass --root with the folder. --config points to another configuration file."$json$::jsonb),
  ('en', 'docs.commandPalette.title', $json$"Command palette and shortcuts"$json$::jsonb),
  ('en', 'docs.commandPalette.summary', $json$"Everything that has a button also has a name in the command palette, and the main screens have keyboard shortcuts."$json$::jsonb),
  ('en', 'docs.commandPalette.usage', $json$"Press Ctrl+K (⌘K on Mac) on any screen and type: go to a page, open a project, chat or organization, start a chat or change the theme."$json$::jsonb),
  ('en', 'docs.contextCache.title', $json$"Context cache"$json$::jsonb),
  ('en', 'docs.contextCache.summary', $json$"The context built for a request is reused for at least five minutes while the files stay the same, so a follow-up request does not search the project again."$json$::jsonb),
  ('en', 'docs.contextCache.usage', $json$"Always on. Changing a file in the project refreshes only what changed."$json$::jsonb),
  ('en', 'docs.entryGate.title', $json$"Entry gate"$json$::jsonb),
  ('en', 'docs.entryGate.summary', $json$"Jev checks every request before any agent runs: what it asks, where it applies and what is missing."$json$::jsonb),
  ('en', 'docs.entryGate.usage', $json$"Always on. When something is missing, the gatehouse shows it and offers to send as written, send the version JayV rewrote, or complete the request."$json$::jsonb),
  ('en', 'docs.exitGate.title', $json$"Exit gate"$json$::jsonb),
  ('en', 'docs.exitGate.summary', $json$"Jev checks the commands and files in every answer against the project's rules before you act on it."$json$::jsonb),
  ('en', 'docs.exitGate.usage', $json$"Always on. An answer that touches a protected file or runs a forbidden command is held, and the gatehouse explains why."$json$::jsonb),
  ('en', 'docs.gateBoard.title', $json$"Gatehouse board"$json$::jsonb),
  ('en', 'docs.gateBoard.summary', $json$"One page with everything Jev let through, asked about or blocked in the project."$json$::jsonb),
  ('en', 'docs.gateBoard.usage', $json$"Open it from the side menu, from the count in the status bar, or with Ctrl+G (⌘G on Mac). Answers you give to the gatehouse become project notes, so it does not ask again."$json$::jsonb),
  ('en', 'docs.leanCode.title', $json$"Lean code"$json$::jsonb),
  ('en', 'docs.leanCode.summary', $json$"In build mode the agent writes the least code that solves the task and reuses what the language, the platform or an installed library already does."$json$::jsonb),
  ('en', 'docs.leanCode.usage', $json$"On by default. Validation, error handling, security and accessibility are never cut. Turn it off under Your level on the Profile page."$json$::jsonb),
  ('en', 'docs.liveFiles.title', $json$"Live files"$json$::jsonb),
  ('en', 'docs.liveFiles.summary', $json$"A panel beside the conversation shows every file the request changes, newest first, with the diff of each one while the agent writes."$json$::jsonb),
  ('en', 'docs.liveFiles.usage', $json$"Click Live in the chat header; it also opens by itself on the first change. Follow the agent to see each file as soon as it changes."$json$::jsonb),
  ('en', 'docs.orgChat.title', $json$"Organization chat"$json$::jsonb),
  ('en', 'docs.orgChat.summary', $json$"One chat that works on every repository of an organization at once, with the agent, the index and the gate seeing all of them."$json$::jsonb),
  ('en', 'docs.orgChat.usage', $json$"On the organization page, click Organization chat. Without an organization folder on this computer, JayV asks for one first."$json$::jsonb),
  ('en', 'docs.organizations.title', $json$"Organizations"$json$::jsonb),
  ('en', 'docs.organizations.summary', $json$"Organizations group people, repositories and the LLM policy the whole team follows."$json$::jsonb),
  ('en', 'docs.organizations.usage', $json$"Create an organization and invite members on the JayV site dashboard. In the app, Ctrl+2 (⌘2 on Mac) opens your organizations and their repositories."$json$::jsonb),
  ('en', 'docs.parallelRequests.title', $json$"Requests in parallel"$json$::jsonb),
  ('en', 'docs.parallelRequests.summary', $json$"When your plan allows more than one request at a time, chats from different projects run at the same time, each with its own agents and index."$json$::jsonb),
  ('en', 'docs.parallelRequests.usage', $json$"Nothing to turn on: send requests in chats of different projects and they no longer wait for each other. Requests in the same project still run one at a time, so two agents never write to the same folder."$json$::jsonb),
  ('en', 'docs.parallelTasks.title', $json$"Parallel agents"$json$::jsonb),
  ('en', 'docs.parallelTasks.summary', $json$"A large build request in a git project is split into up to four parts that touch separate files, each done by a different agent in its own copy of the project."$json$::jsonb),
  ('en', 'docs.parallelTasks.usage', $json$"Turn on Split big requests between agents in Settings › Jev › Routing. The parts run at the same time in git worktrees and the changes come back to your folder."$json$::jsonb),
  ('en', 'docs.planFirst.title', $json$"Plan before building"$json$::jsonb),
  ('en', 'docs.planFirst.summary', $json$"In a complex build request, your strongest reasoning model writes a plan first and the agent picked to build receives it with the request."$json$::jsonb),
  ('en', 'docs.planFirst.usage', $json$"Turn on Plan with one model, build with another in Settings › Jev › Routing. The plan shows up in the progress panel while it is written; if it fails, the build goes ahead as before."$json$::jsonb),
  ('en', 'docs.profilePhoto.title', $json$"Profile photo"$json$::jsonb),
  ('en', 'docs.profilePhoto.summary', $json$"Your own photo, shown in JayV whatever way you sign in — email and password or any linked account."$json$::jsonb),
  ('en', 'docs.profilePhoto.usage', $json$"On the JayV site, open Dashboard › Account, click the photo, choose an image and adjust the crop. The app shows it on its next start; removing it brings back the photo of your linked account."$json$::jsonb),
  ('en', 'docs.progressPanel.title', $json$"Progress panel"$json$::jsonb),
  ('en', 'docs.progressPanel.summary', $json$"A panel next to the side menu shows what JayV is doing now, one step per line, so the conversation keeps the full width."$json$::jsonb),
  ('en', 'docs.progressPanel.usage', $json$"The panel opens by itself while a request runs. Collapse it to a thin strip when you do not need it; in an organization chat it also lists the repositories."$json$::jsonb),
  ('en', 'docs.projectNotes.title', $json$"Project memory"$json$::jsonb),
  ('en', 'docs.projectNotes.summary', $json$"Short notes about the project — how to test, where things live, what not to touch — that the agent gets once at the start of each session."$json$::jsonb),
  ('en', 'docs.projectNotes.usage', $json$"On a project's chats screen, click Project memory and write up to 2,200 characters. Secrets are refused, and the notes sync with your account."$json$::jsonb),
  ('en', 'docs.secondOpinion.title', $json$"Second opinion"$json$::jsonb),
  ('en', 'docs.secondOpinion.summary', $json$"After a request changes the project in build mode, an agent from another provider reads the diff without editing anything and lists the problems it finds."$json$::jsonb),
  ('en', 'docs.secondOpinion.usage', $json$"Turn on Second opinion from another agent in Settings › Jev › Routing. It needs at least two agents enabled; the answer arrives first and the review follows in its own message."$json$::jsonb),
  ('en', 'docs.secretRedaction.title', $json$"Secret redaction"$json$::jsonb),
  ('en', 'docs.secretRedaction.summary', $json$"Keys, tokens and passwords are replaced before any file reaches a model."$json$::jsonb),
  ('en', 'docs.secretRedaction.usage', $json$"Always on in every plan; there is no switch to turn it off."$json$::jsonb),
  ('en', 'docs.sensitiveFiles.title', $json$"Protected files"$json$::jsonb),
  ('en', 'docs.sensitiveFiles.summary', $json$"Files such as .env, private keys and certificates never go into the context, and agents cannot read or edit them."$json$::jsonb),
  ('en', 'docs.sensitiveFiles.usage', $json$"The default list is always applied; add your own patterns under Never read in Settings › App. Claude Code also blocks its own reads and edits of them, and a change any agent makes to a protected file is held at the exit gate."$json$::jsonb),
  ('en', 'docs.stats.title', $json$"Statistics"$json$::jsonb),
  ('en', 'docs.stats.summary', $json$"Token usage, cost, agent quotas and charts per project and per organization."$json$::jsonb),
  ('en', 'docs.stats.usage', $json$"Open Statistics from the side menu or press Ctrl+3 (⌘3 on Mac)."$json$::jsonb),
  ('en', 'docs.stopRequest.title', $json$"Stop a request"$json$::jsonb),
  ('en', 'docs.stopRequest.summary', $json$"A running request can be stopped at any moment: the agent and every process it opened are closed, and what it already said stays in the chat."$json$::jsonb),
  ('en', 'docs.stopRequest.usage', $json$"While a request runs, the Send button turns into Stop. A request waiting in the queue can be removed from it. Every request also stops at the time limit set in Settings › Jev (30 minutes by default)."$json$::jsonb),
  ('en', 'docs.symbolIndex.title', $json$"Symbol index for Claude"$json$::jsonb),
  ('en', 'docs.symbolIndex.summary', $json$"JayV maps where each function, type and class is defined, on your computer and without spending tokens, and Claude Code can ask that map instead of scanning the folder."$json$::jsonb),
  ('en', 'docs.symbolIndex.usage', $json$"Turn on JayV symbol tools in the Claude Code options in Settings, when your plan includes it. The same index is served to any agent by the jayv mcp command."$json$::jsonb),
  ('en', 'docs.twoFactor.title', $json$"Two-factor authentication"$json$::jsonb),
  ('en', 'docs.twoFactor.summary', $json$"Besides the password or the linked account, signing in asks for a code from an authenticator app on your phone."$json$::jsonb),
  ('en', 'docs.twoFactor.usage', $json$"On the JayV site, open Dashboard › Account › Security, scan the QR code with an authenticator app and confirm with the first code."$json$::jsonb),
  ('en', 'docs.updates.title', $json$"Updates and what's new"$json$::jsonb),
  ('en', 'docs.updates.summary', $json$"JayV checks for a new version in the background and, after each update, shows what changed since the last version you saw."$json$::jsonb),
  ('en', 'docs.updates.usage', $json$"When a new version is out, a bar offers What changes and Update now. The full history is in What's new, in the command palette, and on the Release notes page of the site."$json$::jsonb),
  ('en', 'docs.workModes.title', $json$"Work modes: Auto, Planning and Development"$json$::jsonb),
  ('en', 'docs.workModes.summary', $json$"Each chat has a work mode. Planning only reads the project and answers with a plan; Development changes files; Auto lets Jev pick for each request."$json$::jsonb),
  ('en', 'docs.workModes.usage', $json$"Pick the mode under the message box, type /plan, /build or /auto at the start of a message, or press Ctrl+. (⌘. on Mac). When a chat in Planning asks to implement, Jev switches it to Development."$json$::jsonb),
  ('en', 'docs.command.modeAuto', $json$"Jev picks planning or development for each request in this chat."$json$::jsonb),
  ('en', 'docs.command.modePlan', $json$"Puts the chat in Planning: the agent only reads and answers with a plan. Text after the command is sent as the request."$json$::jsonb),
  ('en', 'docs.command.modeBuild', $json$"Puts the chat in Development: the agent changes files in the project. Text after the command is sent as the request."$json$::jsonb),
  ('en', 'docs.command.palette', $json$"Opens the command palette."$json$::jsonb),
  ('en', 'docs.command.projects', $json$"Goes to Projects."$json$::jsonb),
  ('en', 'docs.command.organizations', $json$"Goes to Organizations."$json$::jsonb),
  ('en', 'docs.command.stats', $json$"Goes to Statistics."$json$::jsonb),
  ('en', 'docs.command.system', $json$"Goes to System."$json$::jsonb),
  ('en', 'docs.command.settings', $json$"Opens Settings."$json$::jsonb),
  ('en', 'docs.command.newChat', $json$"Starts a new chat in the open project."$json$::jsonb),
  ('en', 'docs.command.gate', $json$"Opens the gatehouse of the open project."$json$::jsonb),
  ('en', 'docs.command.workMode', $json$"Switches the work mode of the open chat."$json$::jsonb),
  ('en', 'docs.command.cliStatus', $json$"Shows the version, the configuration file, how many agents and models can run and how many files are indexed."$json$::jsonb),
  ('en', 'docs.command.cliRun', $json$"Sends one request through the gate and the router and prints the answer."$json$::jsonb),
  ('en', 'docs.command.cliIndex', $json$"Indexes the project folder and prints how many files went in."$json$::jsonb),
  ('en', 'docs.command.cliVersion', $json$"Prints the installed version."$json$::jsonb),
  ('en', 'docs.command.cliBench', $json$"Runs a task file through JayV and straight to the agent, each in its own copy, and compares rounds and cost."$json$::jsonb),
  ('en', 'docs.command.cliMcp', $json$"Serves the project's symbol index over MCP (stdio) for coding agents."$json$::jsonb),
  ('es', 'docs.adaptiveRouting.title', $json$"Enrutamiento adaptativo"$json$::jsonb),
  ('es', 'docs.adaptiveRouting.summary', $json$"Jev elige qué agente y qué modelo responden a cada solicitud, según el historial de cada modelo por tipo de solicitud."$json$::jsonb),
  ('es', 'docs.adaptiveRouting.usage', $json$"Mantén más de un agente activado en Configuración. Una respuesta que marcas como que no funcionó, o que la portería de salida retiene, le cuesta un punto al modelo. Si el agente elegido no está instalado o no tiene sesión, la solicitud pasa al siguiente."$json$::jsonb),
  ('es', 'docs.agentSessions.title', $json$"Sesiones del agente"$json$::jsonb),
  ('es', 'docs.agentSessions.summary', $json$"Cada chat retoma la sesión de su agente en lugar de volver a leer el proyecto y toda la conversación en cada mensaje."$json$::jsonb),
  ('es', 'docs.agentSessions.usage', $json$"Siempre activo. Una sesión nueva empieza después de 10 solicitudes, o cuando cambian el agente, el modelo o la carpeta."$json$::jsonb),
  ('es', 'docs.agents.title', $json$"Agentes de línea de comandos"$json$::jsonb),
  ('es', 'docs.agents.summary', $json$"JayV no escribe código por sí mismo: orquesta los agentes de código que ya usas — Codex, Claude Code, GitHub Copilot y Cursor Agent — ejecutando la línea de comandos de cada uno en tu computadora."$json$::jsonb),
  ('es', 'docs.agents.usage', $json$"Abre Configuración, activa los agentes instalados en esta computadora y enumera los modelos que puede usar cada uno. Cada CLI mantiene su propio inicio de sesión; ninguna clave ni contraseña pasa por JayV. La página Sistema muestra si cada agente está instalado y responde."$json$::jsonb),
  ('es', 'docs.answerRecall.title', $json$"Respuestas anteriores"$json$::jsonb),
  ('es', 'docs.answerRecall.summary', $json$"Una solicitud casi idéntica a otra ya respondida en otro chat del mismo proyecto parte de esa respuesta en lugar de explorarlo todo de nuevo."$json$::jsonb),
  ('es', 'docs.answerRecall.usage', $json$"Funciona solo cuando tu plan lo incluye. Cada vez que se reutiliza una respuesta anterior, el panel de Jev lo muestra."$json$::jsonb),
  ('es', 'docs.chatSearch.title', $json$"Búsqueda en los chats"$json$::jsonb),
  ('es', 'docs.chatSearch.summary', $json$"Busca palabras en todas las conversaciones de un proyecto, con el fragmento encontrado resaltado."$json$::jsonb),
  ('es', 'docs.chatSearch.usage', $json$"En la pantalla de chats de un proyecto, escribe en el campo de búsqueda. El índice vive en tu computadora y la búsqueda nunca sale a la red."$json$::jsonb),
  ('es', 'docs.cli.title', $json$"JayV en la terminal"$json$::jsonb),
  ('es', 'docs.cli.summary', $json$"El mismo orquestador funciona desde una terminal, con los agentes y modelos configurados en la app."$json$::jsonb),
  ('es', 'docs.cli.usage', $json$"Ejecuta jayv seguido de un comando en la carpeta del proyecto, o pasa la carpeta con --root. --config apunta a otro archivo de configuración."$json$::jsonb),
  ('es', 'docs.commandPalette.title', $json$"Paleta de comandos y atajos"$json$::jsonb),
  ('es', 'docs.commandPalette.summary', $json$"Todo lo que tiene un botón también tiene un nombre en la paleta de comandos, y las pantallas principales tienen atajos de teclado."$json$::jsonb),
  ('es', 'docs.commandPalette.usage', $json$"Pulsa Ctrl+K (⌘K en Mac) en cualquier pantalla y escribe: ir a una página, abrir un proyecto, un chat o una organización, empezar un chat o cambiar el tema."$json$::jsonb),
  ('es', 'docs.contextCache.title', $json$"Caché de contexto"$json$::jsonb),
  ('es', 'docs.contextCache.summary', $json$"El contexto armado para una solicitud se reutiliza durante al menos cinco minutos mientras los archivos no cambien, así la siguiente solicitud no vuelve a buscar en el proyecto."$json$::jsonb),
  ('es', 'docs.contextCache.usage', $json$"Siempre activo. Cambiar un archivo del proyecto actualiza solo lo que cambió."$json$::jsonb),
  ('es', 'docs.entryGate.title', $json$"Portería de entrada"$json$::jsonb),
  ('es', 'docs.entryGate.summary', $json$"Jev revisa cada solicitud antes de que se ejecute cualquier agente: qué pide, dónde se aplica y qué falta."$json$::jsonb),
  ('es', 'docs.entryGate.usage', $json$"Siempre activa. Cuando falta algo, la portería lo muestra y ofrece enviar tal como está, enviar la versión que JayV reescribió o completar la solicitud."$json$::jsonb),
  ('es', 'docs.exitGate.title', $json$"Portería de salida"$json$::jsonb),
  ('es', 'docs.exitGate.summary', $json$"Jev revisa los comandos y archivos de cada respuesta frente a las reglas del proyecto antes de que actúes sobre ella."$json$::jsonb),
  ('es', 'docs.exitGate.usage', $json$"Siempre activa. Una respuesta que toca un archivo protegido o ejecuta un comando prohibido queda retenida, y la portería explica por qué."$json$::jsonb),
  ('es', 'docs.gateBoard.title', $json$"Panel de la portería"$json$::jsonb),
  ('es', 'docs.gateBoard.summary', $json$"Una página con todo lo que Jev dejó pasar, preguntó o bloqueó en el proyecto."$json$::jsonb),
  ('es', 'docs.gateBoard.usage', $json$"Ábrelo desde el menú lateral, desde el contador de la barra de estado o con Ctrl+G (⌘G en Mac). Las respuestas que das a la portería se convierten en notas del proyecto, y no vuelve a preguntar."$json$::jsonb),
  ('es', 'docs.leanCode.title', $json$"Código conciso"$json$::jsonb),
  ('es', 'docs.leanCode.summary', $json$"En modo de desarrollo, el agente escribe el mínimo de código que resuelve la tarea y reutiliza lo que ya hacen el lenguaje, la plataforma o una biblioteca instalada."$json$::jsonb),
  ('es', 'docs.leanCode.usage', $json$"Activado de forma predeterminada. La validación, el manejo de errores, la seguridad y la accesibilidad nunca se recortan. Desactívalo en Tu nivel, en la página Perfil."$json$::jsonb),
  ('es', 'docs.liveFiles.title', $json$"Archivos en vivo"$json$::jsonb),
  ('es', 'docs.liveFiles.summary', $json$"Un panel junto a la conversación muestra cada archivo que cambia la solicitud, del más reciente al más antiguo, con el diff de cada uno mientras el agente escribe."$json$::jsonb),
  ('es', 'docs.liveFiles.usage', $json$"Haz clic en En vivo en la cabecera del chat; también se abre solo con el primer cambio. Sigue al agente para ver cada archivo en cuanto cambia."$json$::jsonb),
  ('es', 'docs.orgChat.title', $json$"Chat de la organización"$json$::jsonb),
  ('es', 'docs.orgChat.summary', $json$"Un chat que trabaja en todos los repositorios de una organización a la vez, con el agente, el índice y la portería viéndolos todos."$json$::jsonb),
  ('es', 'docs.orgChat.usage', $json$"En la página de la organización, haz clic en Chat de la organización. Sin una carpeta de la organización en esta computadora, JayV te pide una primero."$json$::jsonb),
  ('es', 'docs.organizations.title', $json$"Organizaciones"$json$::jsonb),
  ('es', 'docs.organizations.summary', $json$"Las organizaciones reúnen personas, repositorios y la política de LLM que sigue todo el equipo."$json$::jsonb),
  ('es', 'docs.organizations.usage', $json$"Crea una organización e invita a miembros en el panel del sitio de JayV. En la app, Ctrl+2 (⌘2 en Mac) abre tus organizaciones y sus repositorios."$json$::jsonb),
  ('es', 'docs.parallelRequests.title', $json$"Solicitudes en paralelo"$json$::jsonb),
  ('es', 'docs.parallelRequests.summary', $json$"Cuando tu plan permite más de una solicitud a la vez, los chats de proyectos distintos se ejecutan al mismo tiempo, cada uno con sus propios agentes e índice."$json$::jsonb),
  ('es', 'docs.parallelRequests.usage', $json$"No hay nada que activar: envía solicitudes en chats de proyectos distintos y ya no se esperan entre sí. Las solicitudes del mismo proyecto siguen yendo de una en una, para que dos agentes nunca escriban en la misma carpeta."$json$::jsonb),
  ('es', 'docs.parallelTasks.title', $json$"Agentes en paralelo"$json$::jsonb),
  ('es', 'docs.parallelTasks.summary', $json$"Una solicitud de desarrollo grande en un proyecto git se divide en hasta cuatro partes que tocan archivos separados, cada una hecha por un agente distinto en su propia copia del proyecto."$json$::jsonb),
  ('es', 'docs.parallelTasks.usage', $json$"Activa Dividir solicitudes grandes entre agentes en Configuración › Jev › Enrutamiento. Las partes se ejecutan a la vez en git worktrees y los cambios vuelven a tu carpeta."$json$::jsonb),
  ('es', 'docs.planFirst.title', $json$"Planificar antes de construir"$json$::jsonb),
  ('es', 'docs.planFirst.summary', $json$"En una solicitud de desarrollo compleja, tu modelo de razonamiento más fuerte escribe primero un plan, y el agente elegido para construir lo recibe junto con la solicitud."$json$::jsonb),
  ('es', 'docs.planFirst.usage', $json$"Activa Planificar con un modelo, construir con otro en Configuración › Jev › Enrutamiento. El plan aparece en el panel de progreso mientras se escribe; si falla, el desarrollo sigue como antes."$json$::jsonb),
  ('es', 'docs.profilePhoto.title', $json$"Foto de perfil"$json$::jsonb),
  ('es', 'docs.profilePhoto.summary', $json$"Tu propia foto, que JayV muestra sea cual sea la forma en que inicies sesión: correo y contraseña o cualquier cuenta vinculada."$json$::jsonb),
  ('es', 'docs.profilePhoto.usage', $json$"En el sitio de JayV, abre Panel › Cuenta, haz clic en la foto, elige una imagen y ajusta el recorte. La app la muestra la próxima vez que se abra; quitarla trae de vuelta la foto de tu cuenta vinculada."$json$::jsonb),
  ('es', 'docs.progressPanel.title', $json$"Panel de progreso"$json$::jsonb),
  ('es', 'docs.progressPanel.summary', $json$"Un panel junto al menú lateral muestra lo que JayV está haciendo ahora, un paso por línea, para que la conversación conserve todo el ancho."$json$::jsonb),
  ('es', 'docs.progressPanel.usage', $json$"El panel se abre solo mientras se ejecuta una solicitud. Contráelo a una franja fina cuando no lo necesites; en un chat de la organización también enumera los repositorios."$json$::jsonb),
  ('es', 'docs.projectNotes.title', $json$"Memoria del proyecto"$json$::jsonb),
  ('es', 'docs.projectNotes.summary', $json$"Notas breves sobre el proyecto — cómo probar, dónde están las cosas, qué no tocar — que el agente recibe una vez, al comienzo de cada sesión."$json$::jsonb),
  ('es', 'docs.projectNotes.usage', $json$"En la pantalla de chats de un proyecto, haz clic en Memoria del proyecto y escribe hasta 2200 caracteres. Los secretos se rechazan y las notas se sincronizan con tu cuenta."$json$::jsonb),
  ('es', 'docs.secondOpinion.title', $json$"Segunda opinión"$json$::jsonb),
  ('es', 'docs.secondOpinion.summary', $json$"Después de que una solicitud cambia el proyecto en modo de desarrollo, un agente de otro proveedor lee el diff sin editar nada y enumera los problemas que encuentra."$json$::jsonb),
  ('es', 'docs.secondOpinion.usage', $json$"Activa Segunda opinión de otro agente en Configuración › Jev › Enrutamiento. Necesita al menos dos agentes activados; la respuesta llega primero y la revisión viene después, en su propio mensaje."$json$::jsonb),
  ('es', 'docs.secretRedaction.title', $json$"Ocultación de secretos"$json$::jsonb),
  ('es', 'docs.secretRedaction.summary', $json$"Las claves, los tokens y las contraseñas se reemplazan antes de que cualquier archivo llegue a un modelo."$json$::jsonb),
  ('es', 'docs.secretRedaction.usage', $json$"Siempre activa en todos los planes; no hay interruptor para desactivarla."$json$::jsonb),
  ('es', 'docs.sensitiveFiles.title', $json$"Archivos protegidos"$json$::jsonb),
  ('es', 'docs.sensitiveFiles.summary', $json$"Archivos como .env, claves privadas y certificados nunca entran en el contexto, y los agentes no pueden leerlos ni editarlos."$json$::jsonb),
  ('es', 'docs.sensitiveFiles.usage', $json$"La lista predeterminada siempre se aplica; añade tus propios patrones en Nunca leer, en Configuración › Aplicación. Claude Code también bloquea sus propias lecturas y ediciones de esos archivos, y cualquier cambio de un agente en un archivo protegido queda retenido en la portería de salida."$json$::jsonb),
  ('es', 'docs.stats.title', $json$"Estadísticas"$json$::jsonb),
  ('es', 'docs.stats.summary', $json$"Uso de tokens, costo, cuotas de los agentes y gráficos por proyecto y por organización."$json$::jsonb),
  ('es', 'docs.stats.usage', $json$"Abre Estadísticas desde el menú lateral o pulsa Ctrl+3 (⌘3 en Mac)."$json$::jsonb),
  ('es', 'docs.stopRequest.title', $json$"Detener una solicitud"$json$::jsonb),
  ('es', 'docs.stopRequest.summary', $json$"Una solicitud en curso se puede detener en cualquier momento: se cierran el agente y todos los procesos que abrió, y lo que ya dijo queda en el chat."$json$::jsonb),
  ('es', 'docs.stopRequest.usage', $json$"Mientras se ejecuta una solicitud, el botón Enviar se convierte en Detener. Una solicitud que espera en la cola se puede quitar de ella. Toda solicitud también se detiene al llegar al límite de tiempo definido en Configuración › Jev (30 minutos de forma predeterminada)."$json$::jsonb),
  ('es', 'docs.symbolIndex.title', $json$"Índice de símbolos para Claude"$json$::jsonb),
  ('es', 'docs.symbolIndex.summary', $json$"JayV mapea dónde se define cada función, tipo y clase, en tu computadora y sin gastar tokens, y Claude Code puede consultar ese mapa en lugar de recorrer la carpeta."$json$::jsonb),
  ('es', 'docs.symbolIndex.usage', $json$"Activa Herramientas de símbolos de JayV en las opciones de Claude Code, en Configuración, cuando tu plan lo incluya. El mismo índice se sirve a cualquier agente con el comando jayv mcp."$json$::jsonb),
  ('es', 'docs.twoFactor.title', $json$"Autenticación de dos factores"$json$::jsonb),
  ('es', 'docs.twoFactor.summary', $json$"Además de la contraseña o la cuenta vinculada, iniciar sesión pide un código de una app autenticadora en tu teléfono."$json$::jsonb),
  ('es', 'docs.twoFactor.usage', $json$"En el sitio de JayV, abre Panel › Cuenta › Seguridad, escanea el código QR con una app autenticadora y confirma con el primer código."$json$::jsonb),
  ('es', 'docs.updates.title', $json$"Actualizaciones y novedades"$json$::jsonb),
  ('es', 'docs.updates.summary', $json$"JayV busca una versión nueva en segundo plano y, después de cada actualización, muestra lo que cambió desde la última versión que viste."$json$::jsonb),
  ('es', 'docs.updates.usage', $json$"Cuando sale una versión nueva, una barra ofrece Qué cambia y Actualizar ahora. El historial completo está en Novedades de JayV, en la paleta de comandos, y en la página Notas de la versión del sitio."$json$::jsonb),
  ('es', 'docs.workModes.title', $json$"Modos de trabajo: Auto, Planificación y Desarrollo"$json$::jsonb),
  ('es', 'docs.workModes.summary', $json$"Cada chat tiene un modo de trabajo. Planificación solo lee el proyecto y responde con un plan; Desarrollo cambia archivos; Auto deja que Jev elija en cada solicitud."$json$::jsonb),
  ('es', 'docs.workModes.usage', $json$"Elige el modo debajo del cuadro de mensaje, escribe /plan, /build o /auto al comienzo de un mensaje, o pulsa Ctrl+. (⌘. en Mac). Cuando un chat en Planificación pide implementar, Jev lo pasa a Desarrollo."$json$::jsonb),
  ('es', 'docs.command.modeAuto', $json$"Jev elige planificación o desarrollo para cada solicitud de este chat."$json$::jsonb),
  ('es', 'docs.command.modePlan', $json$"Pone el chat en Planificación: el agente solo lee y responde con un plan. El texto después del comando se envía como la solicitud."$json$::jsonb),
  ('es', 'docs.command.modeBuild', $json$"Pone el chat en Desarrollo: el agente cambia archivos del proyecto. El texto después del comando se envía como la solicitud."$json$::jsonb),
  ('es', 'docs.command.palette', $json$"Abre la paleta de comandos."$json$::jsonb),
  ('es', 'docs.command.projects', $json$"Va a Proyectos."$json$::jsonb),
  ('es', 'docs.command.organizations', $json$"Va a Organizaciones."$json$::jsonb),
  ('es', 'docs.command.stats', $json$"Va a Estadísticas."$json$::jsonb),
  ('es', 'docs.command.system', $json$"Va a Sistema."$json$::jsonb),
  ('es', 'docs.command.settings', $json$"Abre Configuración."$json$::jsonb),
  ('es', 'docs.command.newChat', $json$"Empieza un chat nuevo en el proyecto abierto."$json$::jsonb),
  ('es', 'docs.command.gate', $json$"Abre la portería del proyecto abierto."$json$::jsonb),
  ('es', 'docs.command.workMode', $json$"Cambia el modo de trabajo del chat abierto."$json$::jsonb),
  ('es', 'docs.command.cliStatus', $json$"Muestra la versión, el archivo de configuración, cuántos agentes y modelos pueden ejecutarse y cuántos archivos están indexados."$json$::jsonb),
  ('es', 'docs.command.cliRun', $json$"Envía una solicitud a través de la portería y del enrutador e imprime la respuesta."$json$::jsonb),
  ('es', 'docs.command.cliIndex', $json$"Indexa la carpeta del proyecto e imprime cuántos archivos entraron."$json$::jsonb),
  ('es', 'docs.command.cliVersion', $json$"Imprime la versión instalada."$json$::jsonb),
  ('es', 'docs.command.cliBench', $json$"Ejecuta un archivo de tareas a través de JayV y directamente en el agente, cada uno en su propia copia, y compara rondas y costo."$json$::jsonb),
  ('es', 'docs.command.cliMcp', $json$"Sirve el índice de símbolos del proyecto por MCP (stdio) para agentes de código."$json$::jsonb),
  ('zh-CN', 'docs.adaptiveRouting.title', $json$"自适应路由"$json$::jsonb),
  ('zh-CN', 'docs.adaptiveRouting.summary', $json$"Jev 根据每个模型在各类请求上的表现，选择由哪个代理和模型回答每个请求。"$json$::jsonb),
  ('zh-CN', 'docs.adaptiveRouting.usage', $json$"在设置中保持启用多个代理。你标记为没用的回答，或被出口门岗拦下的回答，会让该模型扣一分。如果选中的代理未安装或未登录，请求会转给下一个代理。"$json$::jsonb),
  ('zh-CN', 'docs.agentSessions.title', $json$"代理会话"$json$::jsonb),
  ('zh-CN', 'docs.agentSessions.summary', $json$"每个聊天都会续用其代理的会话，而不是每条消息都重新读取项目和整个对话。"$json$::jsonb),
  ('zh-CN', 'docs.agentSessions.usage', $json$"始终开启。每 10 个请求之后，或代理、模型、文件夹发生变化时，会开始新的会话。"$json$::jsonb),
  ('zh-CN', 'docs.agents.title', $json$"命令行代理"$json$::jsonb),
  ('zh-CN', 'docs.agents.summary', $json$"JayV 自己不写代码：它在你的电脑上运行各个代理自己的命令行，统筹你已经在用的编码代理——Codex、Claude Code、GitHub Copilot 和 Cursor Agent。"$json$::jsonb),
  ('zh-CN', 'docs.agents.usage', $json$"打开设置，启用这台电脑上已安装的代理，并列出每个代理可以使用的模型。每个 CLI 保留自己的登录；任何密钥或密码都不经过 JayV。系统页面会显示每个代理是否已安装并能响应。"$json$::jsonb),
  ('zh-CN', 'docs.answerRecall.title', $json$"以前的回答"$json$::jsonb),
  ('zh-CN', 'docs.answerRecall.summary', $json$"如果某个请求与同一项目其他聊天中已回答的请求几乎相同，就会从那个回答出发，而不是重新探索一切。"$json$::jsonb),
  ('zh-CN', 'docs.answerRecall.usage', $json$"套餐包含时会自动生效。每次复用以前的回答，Jev 面板都会显示。"$json$::jsonb),
  ('zh-CN', 'docs.chatSearch.title', $json$"聊天搜索"$json$::jsonb),
  ('zh-CN', 'docs.chatSearch.summary', $json$"在项目的所有对话中搜索词语，并高亮显示匹配的段落。"$json$::jsonb),
  ('zh-CN', 'docs.chatSearch.usage', $json$"在项目的聊天界面中，于搜索框输入内容。索引保存在你的电脑上，搜索从不经过网络。"$json$::jsonb),
  ('zh-CN', 'docs.cli.title', $json$"在终端中使用 JayV"$json$::jsonb),
  ('zh-CN', 'docs.cli.summary', $json$"同一个编排器也可以在终端中运行，使用在应用中配置好的代理和模型。"$json$::jsonb),
  ('zh-CN', 'docs.cli.usage', $json$"在项目文件夹中运行 jayv 加命令，或用 --root 指定文件夹。--config 指向另一个配置文件。"$json$::jsonb),
  ('zh-CN', 'docs.commandPalette.title', $json$"命令面板和快捷键"$json$::jsonb),
  ('zh-CN', 'docs.commandPalette.summary', $json$"所有有按钮的操作在命令面板中也有名称，主要界面都有键盘快捷键。"$json$::jsonb),
  ('zh-CN', 'docs.commandPalette.usage', $json$"在任何界面按 Ctrl+K（Mac 上为 ⌘K）并输入：前往某个页面，打开项目、聊天或组织，开始聊天或切换主题。"$json$::jsonb),
  ('zh-CN', 'docs.contextCache.title', $json$"上下文缓存"$json$::jsonb),
  ('zh-CN', 'docs.contextCache.summary', $json$"为请求构建的上下文在文件不变时至少复用五分钟，因此后续请求不会再次搜索项目。"$json$::jsonb),
  ('zh-CN', 'docs.contextCache.usage', $json$"始终开启。修改项目中的文件只会刷新变化的部分。"$json$::jsonb),
  ('zh-CN', 'docs.entryGate.title', $json$"入口门岗"$json$::jsonb),
  ('zh-CN', 'docs.entryGate.summary', $json$"Jev 在任何代理运行之前检查每个请求：它要求什么、适用于哪里、缺少什么。"$json$::jsonb),
  ('zh-CN', 'docs.entryGate.usage', $json$"始终开启。缺少信息时，门岗会显示出来，并提供按原样发送、发送 JayV 改写的版本或补全请求三种选择。"$json$::jsonb),
  ('zh-CN', 'docs.exitGate.title', $json$"出口门岗"$json$::jsonb),
  ('zh-CN', 'docs.exitGate.summary', $json$"在你根据回答采取行动之前，Jev 会对照项目规则检查每个回答中的命令和文件。"$json$::jsonb),
  ('zh-CN', 'docs.exitGate.usage', $json$"始终开启。涉及受保护文件或运行被禁止命令的回答会被拦下，门岗会说明原因。"$json$::jsonb),
  ('zh-CN', 'docs.gateBoard.title', $json$"门岗看板"$json$::jsonb),
  ('zh-CN', 'docs.gateBoard.summary', $json$"一个页面汇总 Jev 在项目中放行、询问或拦截的所有内容。"$json$::jsonb),
  ('zh-CN', 'docs.gateBoard.usage', $json$"从侧边菜单、状态栏中的计数或按 Ctrl+G（Mac 上为 ⌘G）打开。你给门岗的回答会变成项目笔记，它不会再问同样的问题。"$json$::jsonb),
  ('zh-CN', 'docs.leanCode.title', $json$"精简代码"$json$::jsonb),
  ('zh-CN', 'docs.leanCode.summary', $json$"在开发模式下，代理写出能解决任务的最少代码，并复用语言、平台或已安装库已有的功能。"$json$::jsonb),
  ('zh-CN', 'docs.leanCode.usage', $json$"默认开启。数据校验、错误处理、安全和无障碍永远不会被删减。可在个人资料页面的“你的级别”中关闭。"$json$::jsonb),
  ('zh-CN', 'docs.liveFiles.title', $json$"实时文件"$json$::jsonb),
  ('zh-CN', 'docs.liveFiles.summary', $json$"对话旁的面板按从新到旧显示请求修改的每个文件，并在代理写入时显示每个文件的差异。"$json$::jsonb),
  ('zh-CN', 'docs.liveFiles.usage', $json$"点击聊天标题栏中的“实时”；第一次修改时它也会自动打开。跟随代理即可在每个文件变化时立刻看到它。"$json$::jsonb),
  ('zh-CN', 'docs.orgChat.title', $json$"组织聊天"$json$::jsonb),
  ('zh-CN', 'docs.orgChat.summary', $json$"一个同时处理组织所有仓库的聊天，代理、索引和门岗都能看到全部仓库。"$json$::jsonb),
  ('zh-CN', 'docs.orgChat.usage', $json$"在组织页面点击“组织聊天”。如果这台电脑上没有组织文件夹，JayV 会先请你指定一个。"$json$::jsonb),
  ('zh-CN', 'docs.organizations.title', $json$"组织"$json$::jsonb),
  ('zh-CN', 'docs.organizations.summary', $json$"组织把成员、仓库和整个团队遵循的 LLM 策略集中在一起。"$json$::jsonb),
  ('zh-CN', 'docs.organizations.usage', $json$"在 JayV 网站的控制台中创建组织并邀请成员。在应用中，Ctrl+2（Mac 上为 ⌘2）打开你的组织及其仓库。"$json$::jsonb),
  ('zh-CN', 'docs.parallelRequests.title', $json$"并行请求"$json$::jsonb),
  ('zh-CN', 'docs.parallelRequests.summary', $json$"当你的套餐允许同时运行多个请求时，不同项目的聊天会同时运行，各自使用自己的代理和索引。"$json$::jsonb),
  ('zh-CN', 'docs.parallelRequests.usage', $json$"无需开启任何设置：在不同项目的聊天中发送请求，它们不再相互等待。同一项目的请求仍逐个进行，因此两个代理绝不会写入同一个文件夹。"$json$::jsonb),
  ('zh-CN', 'docs.parallelTasks.title', $json$"并行代理"$json$::jsonb),
  ('zh-CN', 'docs.parallelTasks.summary', $json$"git 项目中的大型开发请求会被拆分为最多四个涉及不同文件的部分，每部分由不同的代理在各自的项目副本中完成。"$json$::jsonb),
  ('zh-CN', 'docs.parallelTasks.usage', $json$"在设置 › Jev › 路由中开启“把大请求拆分给多个代理”。各部分在 git worktree 中同时运行，修改会回到你的文件夹。"$json$::jsonb),
  ('zh-CN', 'docs.planFirst.title', $json$"先规划后构建"$json$::jsonb),
  ('zh-CN', 'docs.planFirst.summary', $json$"对于复杂的开发请求，你最强的推理模型会先写出计划，被选中负责构建的代理会随请求一起收到该计划。"$json$::jsonb),
  ('zh-CN', 'docs.planFirst.usage', $json$"在设置 › Jev › 路由中开启“用一个模型规划，用另一个模型构建”。计划在编写时就会显示在进度面板中；如果计划失败，开发会照常继续。"$json$::jsonb),
  ('zh-CN', 'docs.profilePhoto.title', $json$"个人资料照片"$json$::jsonb),
  ('zh-CN', 'docs.profilePhoto.summary', $json$"你自己的照片，无论用邮箱和密码还是任何关联账户登录，JayV 都会显示它。"$json$::jsonb),
  ('zh-CN', 'docs.profilePhoto.usage', $json$"在 JayV 网站打开 控制台 › 账户，点击照片，选择图片并调整裁剪。应用会在下次启动时显示它；移除后会恢复为关联账户的照片。"$json$::jsonb),
  ('zh-CN', 'docs.progressPanel.title', $json$"进度面板"$json$::jsonb),
  ('zh-CN', 'docs.progressPanel.summary', $json$"侧边菜单旁的面板逐行显示 JayV 当前正在做的每一步，让对话保持完整宽度。"$json$::jsonb),
  ('zh-CN', 'docs.progressPanel.usage', $json$"请求运行时面板会自动打开。不需要时可将其收起为一条细栏；在组织聊天中它还会列出仓库。"$json$::jsonb),
  ('zh-CN', 'docs.projectNotes.title', $json$"项目记忆"$json$::jsonb),
  ('zh-CN', 'docs.projectNotes.summary', $json$"关于项目的简短笔记——如何测试、东西放在哪里、什么不能动——代理会在每次会话开始时收到一次。"$json$::jsonb),
  ('zh-CN', 'docs.projectNotes.usage', $json$"在项目的聊天界面点击“项目记忆”，最多写 2,200 个字符。机密内容会被拒绝，笔记会与你的账户同步。"$json$::jsonb),
  ('zh-CN', 'docs.secondOpinion.title', $json$"第二意见"$json$::jsonb),
  ('zh-CN', 'docs.secondOpinion.summary', $json$"在请求以开发模式修改项目后，另一家提供商的代理会在不做任何修改的情况下阅读差异，并列出发现的问题。"$json$::jsonb),
  ('zh-CN', 'docs.secondOpinion.usage', $json$"在设置 › Jev › 路由中开启“由另一个代理提供第二意见”。至少需要启用两个代理；回答先到，审查随后以单独的消息发出。"$json$::jsonb),
  ('zh-CN', 'docs.secretRedaction.title', $json$"机密遮蔽"$json$::jsonb),
  ('zh-CN', 'docs.secretRedaction.summary', $json$"密钥、令牌和密码会在任何文件到达模型之前被替换。"$json$::jsonb),
  ('zh-CN', 'docs.secretRedaction.usage', $json$"所有套餐中始终开启，没有关闭开关。"$json$::jsonb),
  ('zh-CN', 'docs.sensitiveFiles.title', $json$"受保护文件"$json$::jsonb),
  ('zh-CN', 'docs.sensitiveFiles.summary', $json$".env、私钥和证书等文件绝不会进入上下文，代理也无法读取或编辑它们。"$json$::jsonb),
  ('zh-CN', 'docs.sensitiveFiles.usage', $json$"默认列表始终生效；可在设置 › 应用 的“禁止读取”中添加你自己的规则。Claude Code 也会阻止自己读取和编辑这些文件，任何代理对受保护文件的修改都会在出口门岗被拦下。"$json$::jsonb),
  ('zh-CN', 'docs.stats.title', $json$"统计"$json$::jsonb),
  ('zh-CN', 'docs.stats.summary', $json$"按项目和组织显示的令牌用量、费用、代理配额和图表。"$json$::jsonb),
  ('zh-CN', 'docs.stats.usage', $json$"从侧边菜单打开统计，或按 Ctrl+3（Mac 上为 ⌘3）。"$json$::jsonb),
  ('zh-CN', 'docs.stopRequest.title', $json$"停止请求"$json$::jsonb),
  ('zh-CN', 'docs.stopRequest.summary', $json$"正在运行的请求可以随时停止：代理及其打开的所有进程都会关闭，它已经说过的内容会保留在聊天中。"$json$::jsonb),
  ('zh-CN', 'docs.stopRequest.usage', $json$"请求运行时，“发送”按钮会变成“停止”。在队列中等待的请求可以从队列中移除。每个请求也会在设置 › Jev 中设定的时间上限（默认 30 分钟）时停止。"$json$::jsonb),
  ('zh-CN', 'docs.symbolIndex.title', $json$"面向 Claude 的符号索引"$json$::jsonb),
  ('zh-CN', 'docs.symbolIndex.summary', $json$"JayV 在你的电脑上记录每个函数、类型和类的定义位置，不消耗令牌，Claude Code 可以查询这张地图，而不用扫描整个文件夹。"$json$::jsonb),
  ('zh-CN', 'docs.symbolIndex.usage', $json$"套餐包含时，在设置的 Claude Code 选项中开启“JayV 符号工具”。同一个索引也可通过 jayv mcp 命令提供给任何代理。"$json$::jsonb),
  ('zh-CN', 'docs.twoFactor.title', $json$"双重身份验证"$json$::jsonb),
  ('zh-CN', 'docs.twoFactor.summary', $json$"除了密码或关联账户外，登录时还需要手机上身份验证器应用中的验证码。"$json$::jsonb),
  ('zh-CN', 'docs.twoFactor.usage', $json$"在 JayV 网站打开 控制台 › 账户 › 安全，用身份验证器应用扫描二维码，并用第一个验证码确认。"$json$::jsonb),
  ('zh-CN', 'docs.updates.title', $json$"更新和新功能"$json$::jsonb),
  ('zh-CN', 'docs.updates.summary', $json$"JayV 在后台检查新版本，并在每次更新后显示自你上次查看的版本以来的变化。"$json$::jsonb),
  ('zh-CN', 'docs.updates.usage', $json$"有新版本时，会出现一个提示栏，提供“更新内容”和“立即更新”。完整历史可在命令面板的“JayV 新功能”以及网站的版本说明页面中查看。"$json$::jsonb),
  ('zh-CN', 'docs.workModes.title', $json$"工作模式：自动、规划和开发"$json$::jsonb),
  ('zh-CN', 'docs.workModes.summary', $json$"每个聊天都有一个工作模式。规划只读取项目并以计划作答；开发会修改文件；自动则由 Jev 针对每个请求选择。"$json$::jsonb),
  ('zh-CN', 'docs.workModes.usage', $json$"在消息框下方选择模式，在消息开头输入 /plan、/build 或 /auto，或按 Ctrl+.（Mac 上为 ⌘.）。当处于规划模式的聊天要求实现时，Jev 会把它切换到开发模式。"$json$::jsonb),
  ('zh-CN', 'docs.command.modeAuto', $json$"由 Jev 为此聊天中的每个请求选择规划或开发。"$json$::jsonb),
  ('zh-CN', 'docs.command.modePlan', $json$"将聊天设为规划：代理只读取并以计划作答。命令后的文字会作为请求发送。"$json$::jsonb),
  ('zh-CN', 'docs.command.modeBuild', $json$"将聊天设为开发：代理会修改项目中的文件。命令后的文字会作为请求发送。"$json$::jsonb),
  ('zh-CN', 'docs.command.palette', $json$"打开命令面板。"$json$::jsonb),
  ('zh-CN', 'docs.command.projects', $json$"前往项目。"$json$::jsonb),
  ('zh-CN', 'docs.command.organizations', $json$"前往组织。"$json$::jsonb),
  ('zh-CN', 'docs.command.stats', $json$"前往统计。"$json$::jsonb),
  ('zh-CN', 'docs.command.system', $json$"前往系统。"$json$::jsonb),
  ('zh-CN', 'docs.command.settings', $json$"打开设置。"$json$::jsonb),
  ('zh-CN', 'docs.command.newChat', $json$"在当前项目中开始新聊天。"$json$::jsonb),
  ('zh-CN', 'docs.command.gate', $json$"打开当前项目的门岗。"$json$::jsonb),
  ('zh-CN', 'docs.command.workMode', $json$"切换当前聊天的工作模式。"$json$::jsonb),
  ('zh-CN', 'docs.command.cliStatus', $json$"显示版本、配置文件、可运行的代理和模型数量以及已索引的文件数量。"$json$::jsonb),
  ('zh-CN', 'docs.command.cliRun', $json$"通过门岗和路由器发送一个请求并输出回答。"$json$::jsonb),
  ('zh-CN', 'docs.command.cliIndex', $json$"为项目文件夹建立索引，并输出收录的文件数量。"$json$::jsonb),
  ('zh-CN', 'docs.command.cliVersion', $json$"输出已安装的版本。"$json$::jsonb),
  ('zh-CN', 'docs.command.cliBench', $json$"分别通过 JayV 和直接在代理中、各自在独立副本里运行任务文件，并比较轮数和费用。"$json$::jsonb),
  ('zh-CN', 'docs.command.cliMcp', $json$"通过 MCP（stdio）向编码代理提供项目的符号索引。"$json$::jsonb),
  ('hi', 'docs.adaptiveRouting.title', $json$"अडैप्टिव रूटिंग"$json$::jsonb),
  ('hi', 'docs.adaptiveRouting.summary', $json$"Jev हर अनुरोध के प्रकार पर हर मॉडल के रिकॉर्ड को देखकर तय करता है कि कौन-सा एजेंट और मॉडल जवाब देगा।"$json$::jsonb),
  ('hi', 'docs.adaptiveRouting.usage', $json$"सेटिंग्स में एक से ज़्यादा एजेंट चालू रखें। जिस जवाब को आप काम न करने वाला बताते हैं, या जिसे निकास गेट रोक देता है, उससे मॉडल का एक अंक कटता है। अगर चुना गया एजेंट मौजूद नहीं है या लॉग इन नहीं है, तो अनुरोध अगले एजेंट को जाता है।"$json$::jsonb),
  ('hi', 'docs.agentSessions.title', $json$"एजेंट सत्र"$json$::jsonb),
  ('hi', 'docs.agentSessions.summary', $json$"हर चैट अपने एजेंट का सत्र जारी रखती है, ताकि हर संदेश पर प्रोजेक्ट और पूरी बातचीत दोबारा न पढ़नी पड़े।"$json$::jsonb),
  ('hi', 'docs.agentSessions.usage', $json$"हमेशा चालू। 10 अनुरोधों के बाद, या एजेंट, मॉडल या फ़ोल्डर बदलने पर नया सत्र शुरू होता है।"$json$::jsonb),
  ('hi', 'docs.agents.title', $json$"कमांड-लाइन एजेंट"$json$::jsonb),
  ('hi', 'docs.agents.summary', $json$"JayV खुद कोड नहीं लिखता: वह उन कोडिंग एजेंटों को चलाता है जिन्हें आप पहले से इस्तेमाल करते हैं — Codex, Claude Code, GitHub Copilot और Cursor Agent — आपके कंप्यूटर पर हर एक की अपनी कमांड लाइन से।"$json$::jsonb),
  ('hi', 'docs.agents.usage', $json$"सेटिंग्स खोलें, इस कंप्यूटर पर इंस्टॉल एजेंट चालू करें और हर एजेंट के मॉडल जोड़ें। हर CLI अपना लॉगिन खुद रखता है; कोई कुंजी या पासवर्ड JayV से होकर नहीं जाता। सिस्टम पेज बताता है कि हर एजेंट इंस्टॉल है और जवाब दे रहा है या नहीं।"$json$::jsonb),
  ('hi', 'docs.answerRecall.title', $json$"पिछले जवाब"$json$::jsonb),
  ('hi', 'docs.answerRecall.summary', $json$"जो अनुरोध उसी प्रोजेक्ट की किसी दूसरी चैट में पहले दिए गए जवाब से लगभग मिलता है, वह सब कुछ दोबारा खोजने के बजाय उसी जवाब से शुरू होता है।"$json$::jsonb),
  ('hi', 'docs.answerRecall.usage', $json$"आपके प्लान में शामिल हो तो अपने आप काम करता है। जब भी कोई पिछला जवाब दोबारा इस्तेमाल होता है, Jev पैनल दिखाता है।"$json$::jsonb),
  ('hi', 'docs.chatSearch.title', $json$"चैट खोज"$json$::jsonb),
  ('hi', 'docs.chatSearch.summary', $json$"किसी प्रोजेक्ट की सभी बातचीत में शब्द खोजें, मिला हुआ हिस्सा हाइलाइट होकर दिखता है।"$json$::jsonb),
  ('hi', 'docs.chatSearch.usage', $json$"प्रोजेक्ट की चैट स्क्रीन पर खोज फ़ील्ड में टाइप करें। इंडेक्स आपके कंप्यूटर पर रहता है और खोज कभी नेटवर्क पर नहीं जाती।"$json$::jsonb),
  ('hi', 'docs.cli.title', $json$"टर्मिनल में JayV"$json$::jsonb),
  ('hi', 'docs.cli.summary', $json$"वही ऑर्केस्ट्रेटर टर्मिनल से चलता है, ऐप में सेट किए गए एजेंटों और मॉडलों के साथ।"$json$::jsonb),
  ('hi', 'docs.cli.usage', $json$"प्रोजेक्ट फ़ोल्डर में jayv के बाद कोई कमांड चलाएँ, या --root से फ़ोल्डर बताएँ। --config किसी दूसरी कॉन्फ़िगरेशन फ़ाइल की ओर इशारा करता है।"$json$::jsonb),
  ('hi', 'docs.commandPalette.title', $json$"कमांड पैलेट और शॉर्टकट"$json$::jsonb),
  ('hi', 'docs.commandPalette.summary', $json$"जिस चीज़ का बटन है, उसका कमांड पैलेट में नाम भी है, और मुख्य स्क्रीनों के कीबोर्ड शॉर्टकट हैं।"$json$::jsonb),
  ('hi', 'docs.commandPalette.usage', $json$"किसी भी स्क्रीन पर Ctrl+K (Mac पर ⌘K) दबाएँ और टाइप करें: किसी पेज पर जाएँ, कोई प्रोजेक्ट, चैट या संगठन खोलें, चैट शुरू करें या थीम बदलें।"$json$::jsonb),
  ('hi', 'docs.contextCache.title', $json$"कॉन्टेक्स्ट कैश"$json$::jsonb),
  ('hi', 'docs.contextCache.summary', $json$"किसी अनुरोध के लिए बना कॉन्टेक्स्ट, फ़ाइलें न बदलने तक कम से कम पाँच मिनट दोबारा इस्तेमाल होता है, इसलिए अगला अनुरोध प्रोजेक्ट में फिर से नहीं खोजता।"$json$::jsonb),
  ('hi', 'docs.contextCache.usage', $json$"हमेशा चालू। प्रोजेक्ट की कोई फ़ाइल बदलने पर सिर्फ़ बदला हुआ हिस्सा ताज़ा होता है।"$json$::jsonb),
  ('hi', 'docs.entryGate.title', $json$"प्रवेश गेट"$json$::jsonb),
  ('hi', 'docs.entryGate.summary', $json$"कोई भी एजेंट चलने से पहले Jev हर अनुरोध जाँचता है: वह क्या माँगता है, कहाँ लागू होता है और क्या कमी है।"$json$::jsonb),
  ('hi', 'docs.entryGate.usage', $json$"हमेशा चालू। जब कुछ कमी होती है, गेट उसे दिखाता है और विकल्प देता है: जैसा लिखा है वैसा भेजें, JayV का दोबारा लिखा संस्करण भेजें, या अनुरोध पूरा करें।"$json$::jsonb),
  ('hi', 'docs.exitGate.title', $json$"निकास गेट"$json$::jsonb),
  ('hi', 'docs.exitGate.summary', $json$"आप किसी जवाब पर काम करें, उससे पहले Jev उसके कमांड और फ़ाइलों को प्रोजेक्ट के नियमों से मिलाता है।"$json$::jsonb),
  ('hi', 'docs.exitGate.usage', $json$"हमेशा चालू। जो जवाब किसी सुरक्षित फ़ाइल को छूता है या कोई मना किया गया कमांड चलाता है, वह रोक लिया जाता है और गेट कारण बताता है।"$json$::jsonb),
  ('hi', 'docs.gateBoard.title', $json$"गेट बोर्ड"$json$::jsonb),
  ('hi', 'docs.gateBoard.summary', $json$"एक पेज, जिसमें वह सब है जो Jev ने प्रोजेक्ट में आगे जाने दिया, पूछा या रोका।"$json$::jsonb),
  ('hi', 'docs.gateBoard.usage', $json$"इसे साइड मेन्यू से, स्टेटस बार की गिनती से, या Ctrl+G (Mac पर ⌘G) से खोलें। गेट को दिए आपके जवाब प्रोजेक्ट नोट्स बन जाते हैं, ताकि वह दोबारा न पूछे।"$json$::jsonb),
  ('hi', 'docs.leanCode.title', $json$"संक्षिप्त कोड"$json$::jsonb),
  ('hi', 'docs.leanCode.summary', $json$"डेवलपमेंट मोड में एजेंट काम हल करने वाला कम से कम कोड लिखता है और भाषा, प्लेटफ़ॉर्म या इंस्टॉल लाइब्रेरी की मौजूदा क्षमता का इस्तेमाल करता है।"$json$::jsonb),
  ('hi', 'docs.leanCode.usage', $json$"डिफ़ॉल्ट रूप से चालू। वैलिडेशन, एरर हैंडलिंग, सुरक्षा और सुलभता में कभी कटौती नहीं होती। इसे प्रोफ़ाइल पेज पर आपका स्तर में बंद करें।"$json$::jsonb),
  ('hi', 'docs.liveFiles.title', $json$"लाइव फ़ाइलें"$json$::jsonb),
  ('hi', 'docs.liveFiles.summary', $json$"बातचीत के बगल वाला पैनल अनुरोध से बदलने वाली हर फ़ाइल को नई से पुरानी क्रम में दिखाता है, और एजेंट के लिखते समय हर फ़ाइल का diff भी।"$json$::jsonb),
  ('hi', 'docs.liveFiles.usage', $json$"चैट हेडर में लाइव पर क्लिक करें; पहले बदलाव पर यह अपने आप भी खुलता है। हर फ़ाइल बदलते ही देखने के लिए एजेंट को फ़ॉलो करें।"$json$::jsonb),
  ('hi', 'docs.orgChat.title', $json$"संगठन चैट"$json$::jsonb),
  ('hi', 'docs.orgChat.summary', $json$"एक चैट जो किसी संगठन की सभी रिपॉज़िटरी पर एक साथ काम करती है, और एजेंट, इंडेक्स व गेट सबको देखते हैं।"$json$::jsonb),
  ('hi', 'docs.orgChat.usage', $json$"संगठन के पेज पर संगठन चैट पर क्लिक करें। अगर इस कंप्यूटर पर संगठन का फ़ोल्डर नहीं है, तो JayV पहले फ़ोल्डर माँगता है।"$json$::jsonb),
  ('hi', 'docs.organizations.title', $json$"संगठन"$json$::jsonb),
  ('hi', 'docs.organizations.summary', $json$"संगठन लोगों, रिपॉज़िटरी और उस LLM नीति को साथ रखते हैं जिसे पूरी टीम मानती है।"$json$::jsonb),
  ('hi', 'docs.organizations.usage', $json$"JayV साइट के डैशबोर्ड में संगठन बनाएँ और सदस्यों को आमंत्रित करें। ऐप में Ctrl+2 (Mac पर ⌘2) आपके संगठन और उनकी रिपॉज़िटरी खोलता है।"$json$::jsonb),
  ('hi', 'docs.parallelRequests.title', $json$"समानांतर अनुरोध"$json$::jsonb),
  ('hi', 'docs.parallelRequests.summary', $json$"जब आपका प्लान एक साथ एक से ज़्यादा अनुरोध की अनुमति देता है, तो अलग-अलग प्रोजेक्टों की चैट एक साथ चलती हैं, हर एक अपने एजेंटों और इंडेक्स के साथ।"$json$::jsonb),
  ('hi', 'docs.parallelRequests.usage', $json$"कुछ चालू करने की ज़रूरत नहीं: अलग-अलग प्रोजेक्टों की चैट में अनुरोध भेजें, वे अब एक-दूसरे का इंतज़ार नहीं करते। एक ही प्रोजेक्ट के अनुरोध अब भी एक-एक करके चलते हैं, ताकि दो एजेंट कभी एक ही फ़ोल्डर में न लिखें।"$json$::jsonb),
  ('hi', 'docs.parallelTasks.title', $json$"समानांतर एजेंट"$json$::jsonb),
  ('hi', 'docs.parallelTasks.summary', $json$"git प्रोजेक्ट में बड़ा डेवलपमेंट अनुरोध अलग-अलग फ़ाइलों वाले चार हिस्सों तक में बँटता है, और हर हिस्सा अलग एजेंट प्रोजेक्ट की अपनी कॉपी में करता है।"$json$::jsonb),
  ('hi', 'docs.parallelTasks.usage', $json$"सेटिंग्स › Jev › रूटिंग में बड़े अनुरोध एजेंटों में बाँटें चालू करें। हिस्से git worktree में एक साथ चलते हैं और बदलाव आपके फ़ोल्डर में लौट आते हैं।"$json$::jsonb),
  ('hi', 'docs.planFirst.title', $json$"बनाने से पहले योजना"$json$::jsonb),
  ('hi', 'docs.planFirst.summary', $json$"जटिल डेवलपमेंट अनुरोध में आपका सबसे मज़बूत रीज़निंग मॉडल पहले योजना लिखता है, और बनाने के लिए चुना गया एजेंट उसे अनुरोध के साथ पाता है।"$json$::jsonb),
  ('hi', 'docs.planFirst.usage', $json$"सेटिंग्स › Jev › रूटिंग में एक मॉडल से योजना, दूसरे से निर्माण चालू करें। योजना लिखते समय ही प्रगति पैनल में दिखती है; अगर वह विफल होती है, तो डेवलपमेंट पहले की तरह चलता है।"$json$::jsonb),
  ('hi', 'docs.profilePhoto.title', $json$"प्रोफ़ाइल फ़ोटो"$json$::jsonb),
  ('hi', 'docs.profilePhoto.summary', $json$"आपकी अपनी फ़ोटो, जो JayV में दिखती है चाहे आप ईमेल और पासवर्ड से साइन इन करें या किसी लिंक किए गए खाते से।"$json$::jsonb),
  ('hi', 'docs.profilePhoto.usage', $json$"JayV साइट पर डैशबोर्ड › खाता खोलें, फ़ोटो पर क्लिक करें, इमेज चुनें और क्रॉप ठीक करें। ऐप उसे अगली बार खुलने पर दिखाता है; हटाने पर लिंक किए गए खाते की फ़ोटो वापस आ जाती है।"$json$::jsonb),
  ('hi', 'docs.progressPanel.title', $json$"प्रगति पैनल"$json$::jsonb),
  ('hi', 'docs.progressPanel.summary', $json$"साइड मेन्यू के बगल का पैनल दिखाता है कि JayV अभी क्या कर रहा है, हर पंक्ति में एक कदम, ताकि बातचीत को पूरी चौड़ाई मिले।"$json$::jsonb),
  ('hi', 'docs.progressPanel.usage', $json$"अनुरोध चलते समय पैनल अपने आप खुलता है। ज़रूरत न हो तो उसे पतली पट्टी में समेट दें; संगठन चैट में यह रिपॉज़िटरी भी दिखाता है।"$json$::jsonb),
  ('hi', 'docs.projectNotes.title', $json$"प्रोजेक्ट मेमोरी"$json$::jsonb),
  ('hi', 'docs.projectNotes.summary', $json$"प्रोजेक्ट के बारे में छोटे नोट्स — कैसे टेस्ट करें, चीज़ें कहाँ हैं, किसे न छुएँ — जो एजेंट को हर सत्र की शुरुआत में एक बार मिलते हैं।"$json$::jsonb),
  ('hi', 'docs.projectNotes.usage', $json$"प्रोजेक्ट की चैट स्क्रीन पर प्रोजेक्ट मेमोरी पर क्लिक करें और 2,200 अक्षरों तक लिखें। सीक्रेट स्वीकार नहीं होते, और नोट्स आपके खाते के साथ सिंक होते हैं।"$json$::jsonb),
  ('hi', 'docs.secondOpinion.title', $json$"दूसरी राय"$json$::jsonb),
  ('hi', 'docs.secondOpinion.summary', $json$"जब कोई अनुरोध डेवलपमेंट मोड में प्रोजेक्ट बदलता है, तो दूसरे प्रोवाइडर का एजेंट बिना कुछ बदले diff पढ़ता है और मिली समस्याओं की सूची देता है।"$json$::jsonb),
  ('hi', 'docs.secondOpinion.usage', $json$"सेटिंग्स › Jev › रूटिंग में दूसरे एजेंट की दूसरी राय चालू करें। इसके लिए कम से कम दो एजेंट चालू होने चाहिए; पहले जवाब आता है और समीक्षा अलग संदेश में आती है।"$json$::jsonb),
  ('hi', 'docs.secretRedaction.title', $json$"सीक्रेट छिपाना"$json$::jsonb),
  ('hi', 'docs.secretRedaction.summary', $json$"कोई भी फ़ाइल मॉडल तक पहुँचने से पहले कुंजियाँ, टोकन और पासवर्ड बदल दिए जाते हैं।"$json$::jsonb),
  ('hi', 'docs.secretRedaction.usage', $json$"हर प्लान में हमेशा चालू; इसे बंद करने का कोई स्विच नहीं है।"$json$::jsonb),
  ('hi', 'docs.sensitiveFiles.title', $json$"सुरक्षित फ़ाइलें"$json$::jsonb),
  ('hi', 'docs.sensitiveFiles.summary', $json$".env, निजी कुंजियाँ और सर्टिफ़िकेट जैसी फ़ाइलें कभी कॉन्टेक्स्ट में नहीं जातीं, और एजेंट उन्हें पढ़ या बदल नहीं सकते।"$json$::jsonb),
  ('hi', 'docs.sensitiveFiles.usage', $json$"डिफ़ॉल्ट सूची हमेशा लागू रहती है; अपने पैटर्न सेटिंग्स › ऐप में कभी न पढ़ें में जोड़ें। Claude Code भी इन फ़ाइलों को पढ़ना और बदलना खुद रोकता है, और किसी भी एजेंट का सुरक्षित फ़ाइल में किया बदलाव निकास गेट पर रोका जाता है।"$json$::jsonb),
  ('hi', 'docs.stats.title', $json$"आँकड़े"$json$::jsonb),
  ('hi', 'docs.stats.summary', $json$"प्रोजेक्ट और संगठन के हिसाब से टोकन उपयोग, लागत, एजेंट कोटा और चार्ट।"$json$::jsonb),
  ('hi', 'docs.stats.usage', $json$"साइड मेन्यू से आँकड़े खोलें या Ctrl+3 (Mac पर ⌘3) दबाएँ।"$json$::jsonb),
  ('hi', 'docs.stopRequest.title', $json$"अनुरोध रोकें"$json$::jsonb),
  ('hi', 'docs.stopRequest.summary', $json$"चल रहे अनुरोध को कभी भी रोका जा सकता है: एजेंट और उसकी खोली सभी प्रोसेस बंद हो जाती हैं, और वह जो कह चुका है वह चैट में रहता है।"$json$::jsonb),
  ('hi', 'docs.stopRequest.usage', $json$"अनुरोध चलते समय भेजें बटन रोकें बन जाता है। कतार में इंतज़ार कर रहे अनुरोध को उससे हटाया जा सकता है। हर अनुरोध सेटिंग्स › Jev में तय समय-सीमा (डिफ़ॉल्ट 30 मिनट) पर भी रुक जाता है।"$json$::jsonb),
  ('hi', 'docs.symbolIndex.title', $json$"Claude के लिए सिंबल इंडेक्स"$json$::jsonb),
  ('hi', 'docs.symbolIndex.summary', $json$"JayV आपके कंप्यूटर पर, बिना टोकन खर्च किए, दर्ज करता है कि हर फ़ंक्शन, टाइप और क्लास कहाँ परिभाषित है, और Claude Code फ़ोल्डर खंगालने के बजाय इस नक्शे से पूछ सकता है।"$json$::jsonb),
  ('hi', 'docs.symbolIndex.usage', $json$"आपके प्लान में शामिल हो तो सेटिंग्स में Claude Code के विकल्पों में JayV सिंबल टूल चालू करें। यही इंडेक्स jayv mcp कमांड से किसी भी एजेंट को मिलता है।"$json$::jsonb),
  ('hi', 'docs.twoFactor.title', $json$"दो-चरणीय प्रमाणीकरण"$json$::jsonb),
  ('hi', 'docs.twoFactor.summary', $json$"पासवर्ड या लिंक किए गए खाते के अलावा, साइन इन करते समय आपके फ़ोन के ऑथेंटिकेटर ऐप का कोड माँगा जाता है।"$json$::jsonb),
  ('hi', 'docs.twoFactor.usage', $json$"JayV साइट पर डैशबोर्ड › खाता › सुरक्षा खोलें, ऑथेंटिकेटर ऐप से QR कोड स्कैन करें और पहले कोड से पुष्टि करें।"$json$::jsonb),
  ('hi', 'docs.updates.title', $json$"अपडेट और नया क्या है"$json$::jsonb),
  ('hi', 'docs.updates.summary', $json$"JayV बैकग्राउंड में नए संस्करण की जाँच करता है और हर अपडेट के बाद दिखाता है कि आपके पिछली बार देखे संस्करण के बाद क्या बदला।"$json$::jsonb),
  ('hi', 'docs.updates.usage', $json$"नया संस्करण आने पर एक बार में क्या बदलता है और अभी अपडेट करें दिखते हैं। पूरा इतिहास कमांड पैलेट के JayV में नया क्या है में और साइट के रिलीज़ नोट्स पेज पर है।"$json$::jsonb),
  ('hi', 'docs.workModes.title', $json$"कार्य मोड: ऑटो, योजना और डेवलपमेंट"$json$::jsonb),
  ('hi', 'docs.workModes.summary', $json$"हर चैट का एक कार्य मोड होता है। योजना सिर्फ़ प्रोजेक्ट पढ़कर योजना देता है; डेवलपमेंट फ़ाइलें बदलता है; ऑटो में Jev हर अनुरोध के लिए चुनता है।"$json$::jsonb),
  ('hi', 'docs.workModes.usage', $json$"संदेश बॉक्स के नीचे मोड चुनें, संदेश की शुरुआत में /plan, /build या /auto टाइप करें, या Ctrl+. (Mac पर ⌘.) दबाएँ। जब योजना मोड वाली चैट लागू करने को कहती है, तो Jev उसे डेवलपमेंट में बदल देता है।"$json$::jsonb),
  ('hi', 'docs.command.modeAuto', $json$"इस चैट के हर अनुरोध के लिए Jev योजना या डेवलपमेंट चुनता है।"$json$::jsonb),
  ('hi', 'docs.command.modePlan', $json$"चैट को योजना मोड में रखता है: एजेंट सिर्फ़ पढ़ता है और योजना देता है। कमांड के बाद का टेक्स्ट अनुरोध के रूप में जाता है।"$json$::jsonb),
  ('hi', 'docs.command.modeBuild', $json$"चैट को डेवलपमेंट मोड में रखता है: एजेंट प्रोजेक्ट की फ़ाइलें बदलता है। कमांड के बाद का टेक्स्ट अनुरोध के रूप में जाता है।"$json$::jsonb),
  ('hi', 'docs.command.palette', $json$"कमांड पैलेट खोलता है।"$json$::jsonb),
  ('hi', 'docs.command.projects', $json$"प्रोजेक्ट पर जाता है।"$json$::jsonb),
  ('hi', 'docs.command.organizations', $json$"संगठन पर जाता है।"$json$::jsonb),
  ('hi', 'docs.command.stats', $json$"आँकड़े पर जाता है।"$json$::jsonb),
  ('hi', 'docs.command.system', $json$"सिस्टम पर जाता है।"$json$::jsonb),
  ('hi', 'docs.command.settings', $json$"सेटिंग्स खोलता है।"$json$::jsonb),
  ('hi', 'docs.command.newChat', $json$"खुले प्रोजेक्ट में नई चैट शुरू करता है।"$json$::jsonb),
  ('hi', 'docs.command.gate', $json$"खुले प्रोजेक्ट का गेट खोलता है।"$json$::jsonb),
  ('hi', 'docs.command.workMode', $json$"खुली चैट का कार्य मोड बदलता है।"$json$::jsonb),
  ('hi', 'docs.command.cliStatus', $json$"संस्करण, कॉन्फ़िगरेशन फ़ाइल, कितने एजेंट और मॉडल चल सकते हैं और कितनी फ़ाइलें इंडेक्स हैं, यह दिखाता है।"$json$::jsonb),
  ('hi', 'docs.command.cliRun', $json$"एक अनुरोध गेट और राउटर से होकर भेजता है और जवाब प्रिंट करता है।"$json$::jsonb),
  ('hi', 'docs.command.cliIndex', $json$"प्रोजेक्ट फ़ोल्डर का इंडेक्स बनाता है और बताता है कि कितनी फ़ाइलें शामिल हुईं।"$json$::jsonb),
  ('hi', 'docs.command.cliVersion', $json$"इंस्टॉल किया गया संस्करण प्रिंट करता है।"$json$::jsonb),
  ('hi', 'docs.command.cliBench', $json$"किसी टास्क फ़ाइल को JayV से और सीधे एजेंट से, हर एक को उसकी अपनी कॉपी में चलाता है, और राउंड व लागत की तुलना करता है।"$json$::jsonb),
  ('hi', 'docs.command.cliMcp', $json$"प्रोजेक्ट का सिंबल इंडेक्स MCP (stdio) पर कोडिंग एजेंटों को देता है।"$json$::jsonb),
  ('ar', 'docs.adaptiveRouting.title', $json$"التوجيه التكيّفي"$json$::jsonb),
  ('ar', 'docs.adaptiveRouting.summary', $json$"يختار Jev الوكيل والنموذج اللذين يجيبان عن كل طلب، بناءً على سجل كل نموذج في كل نوع من الطلبات."$json$::jsonb),
  ('ar', 'docs.adaptiveRouting.usage', $json$"أبقِ أكثر من وكيل مفعّلًا في الإعدادات. الإجابة التي تقول إنها لم تنجح، أو التي تحتجزها بوابة الخروج، تكلّف النموذج نقطة. إذا لم يكن الوكيل المختار مثبتًا أو لم يسجّل الدخول، ينتقل الطلب إلى الوكيل التالي."$json$::jsonb),
  ('ar', 'docs.agentSessions.title', $json$"جلسات الوكيل"$json$::jsonb),
  ('ar', 'docs.agentSessions.summary', $json$"تستأنف كل دردشة جلسة وكيلها بدل إعادة قراءة المشروع والمحادثة كاملة مع كل رسالة."$json$::jsonb),
  ('ar', 'docs.agentSessions.usage', $json$"مفعّلة دائمًا. تبدأ جلسة جديدة بعد 10 طلبات، أو عند تغيّر الوكيل أو النموذج أو المجلد."$json$::jsonb),
  ('ar', 'docs.agents.title', $json$"وكلاء سطر الأوامر"$json$::jsonb),
  ('ar', 'docs.agents.summary', $json$"لا يكتب JayV الشيفرة بنفسه: بل ينسّق وكلاء البرمجة الذين تستخدمهم أصلًا — Codex وClaude Code وGitHub Copilot وCursor Agent — بتشغيل سطر أوامر كل منهم على حاسوبك."$json$::jsonb),
  ('ar', 'docs.agents.usage', $json$"افتح الإعدادات، وفعّل الوكلاء المثبّتين على هذا الحاسوب، وأدرج النماذج التي يمكن لكل منهم استخدامها. تحتفظ كل CLI بتسجيل دخولها؛ ولا يمر أي مفتاح أو كلمة مرور عبر JayV. تُظهر صفحة النظام ما إذا كان كل وكيل مثبتًا ويستجيب."$json$::jsonb),
  ('ar', 'docs.answerRecall.title', $json$"الإجابات السابقة"$json$::jsonb),
  ('ar', 'docs.answerRecall.summary', $json$"الطلب المطابق تقريبًا لطلب سبقت الإجابة عنه في دردشة أخرى من المشروع نفسه يبدأ من تلك الإجابة بدل استكشاف كل شيء من جديد."$json$::jsonb),
  ('ar', 'docs.answerRecall.usage', $json$"تعمل تلقائيًا عندما يتضمنها اشتراكك. في كل مرة تُعاد فيها إجابة سابقة، تظهر في لوحة Jev."$json$::jsonb),
  ('ar', 'docs.chatSearch.title', $json$"البحث في الدردشات"$json$::jsonb),
  ('ar', 'docs.chatSearch.summary', $json$"ابحث عن كلمات في كل محادثات المشروع، مع تمييز المقطع المطابق."$json$::jsonb),
  ('ar', 'docs.chatSearch.usage', $json$"في شاشة دردشات المشروع، اكتب في حقل البحث. يبقى الفهرس على حاسوبك ولا يخرج البحث إلى الشبكة أبدًا."$json$::jsonb),
  ('ar', 'docs.cli.title', $json$"JayV في الطرفية"$json$::jsonb),
  ('ar', 'docs.cli.summary', $json$"يعمل المنسّق نفسه من الطرفية، بالوكلاء والنماذج المضبوطة في التطبيق."$json$::jsonb),
  ('ar', 'docs.cli.usage', $json$"شغّل jayv متبوعًا بأمر في مجلد المشروع، أو مرّر المجلد باستخدام --root. ويشير --config إلى ملف إعدادات آخر."$json$::jsonb),
  ('ar', 'docs.commandPalette.title', $json$"لوحة الأوامر والاختصارات"$json$::jsonb),
  ('ar', 'docs.commandPalette.summary', $json$"كل ما له زر له أيضًا اسم في لوحة الأوامر، وللشاشات الرئيسية اختصارات لوحة مفاتيح."$json$::jsonb),
  ('ar', 'docs.commandPalette.usage', $json$"اضغط Ctrl+K (⌘K على Mac) في أي شاشة واكتب: للانتقال إلى صفحة، أو فتح مشروع أو دردشة أو مؤسسة، أو بدء دردشة، أو تغيير السمة."$json$::jsonb),
  ('ar', 'docs.contextCache.title', $json$"ذاكرة السياق المؤقتة"$json$::jsonb),
  ('ar', 'docs.contextCache.summary', $json$"يُعاد استخدام السياق المبني لطلب ما خمس دقائق على الأقل ما دامت الملفات لم تتغير، فلا يبحث الطلب التالي في المشروع من جديد."$json$::jsonb),
  ('ar', 'docs.contextCache.usage', $json$"مفعّلة دائمًا. تغيير ملف في المشروع يحدّث ما تغيّر فقط."$json$::jsonb),
  ('ar', 'docs.entryGate.title', $json$"بوابة الدخول"$json$::jsonb),
  ('ar', 'docs.entryGate.summary', $json$"يفحص Jev كل طلب قبل تشغيل أي وكيل: ماذا يطلب، وأين ينطبق، وما الناقص."$json$::jsonb),
  ('ar', 'docs.entryGate.usage', $json$"مفعّلة دائمًا. عندما ينقص شيء، تعرضه البوابة وتقترح الإرسال كما هو، أو إرسال النسخة التي أعاد JayV كتابتها، أو إكمال الطلب."$json$::jsonb),
  ('ar', 'docs.exitGate.title', $json$"بوابة الخروج"$json$::jsonb),
  ('ar', 'docs.exitGate.summary', $json$"يفحص Jev الأوامر والملفات في كل إجابة وفق قواعد المشروع قبل أن تتصرف بناءً عليها."$json$::jsonb),
  ('ar', 'docs.exitGate.usage', $json$"مفعّلة دائمًا. الإجابة التي تمس ملفًا محميًا أو تشغّل أمرًا ممنوعًا تُحتجز، وتشرح البوابة السبب."$json$::jsonb),
  ('ar', 'docs.gateBoard.title', $json$"لوحة البوابة"$json$::jsonb),
  ('ar', 'docs.gateBoard.summary', $json$"صفحة واحدة بكل ما سمح به Jev أو سأل عنه أو منعه في المشروع."$json$::jsonb),
  ('ar', 'docs.gateBoard.usage', $json$"افتحها من القائمة الجانبية، أو من العدّاد في شريط الحالة، أو بـ Ctrl+G (⌘G على Mac). تتحول إجاباتك للبوابة إلى ملاحظات للمشروع، فلا تسأل عنها مجددًا."$json$::jsonb),
  ('ar', 'docs.leanCode.title', $json$"شيفرة موجزة"$json$::jsonb),
  ('ar', 'docs.leanCode.summary', $json$"في وضع التطوير، يكتب الوكيل أقل قدر من الشيفرة يحل المهمة، ويعيد استخدام ما تقدمه اللغة أو المنصة أو مكتبة مثبّتة."$json$::jsonb),
  ('ar', 'docs.leanCode.usage', $json$"مفعّلة افتراضيًا. لا يُختصر التحقق من المدخلات ومعالجة الأخطاء والأمان وإمكانية الوصول أبدًا. أوقفها من مستواك في صفحة الملف الشخصي."$json$::jsonb),
  ('ar', 'docs.liveFiles.title', $json$"الملفات المباشرة"$json$::jsonb),
  ('ar', 'docs.liveFiles.summary', $json$"لوحة بجوار المحادثة تعرض كل ملف يغيّره الطلب، من الأحدث إلى الأقدم، مع الفروق في كل ملف أثناء كتابة الوكيل."$json$::jsonb),
  ('ar', 'docs.liveFiles.usage', $json$"انقر مباشر في ترويسة الدردشة؛ وتفتح أيضًا تلقائيًا مع أول تغيير. تابع الوكيل لترى كل ملف فور تغيّره."$json$::jsonb),
  ('ar', 'docs.orgChat.title', $json$"دردشة المؤسسة"$json$::jsonb),
  ('ar', 'docs.orgChat.summary', $json$"دردشة واحدة تعمل على كل مستودعات المؤسسة دفعة واحدة، ويرى الوكيل والفهرس والبوابة جميعها."$json$::jsonb),
  ('ar', 'docs.orgChat.usage', $json$"في صفحة المؤسسة، انقر دردشة المؤسسة. إن لم يكن على هذا الحاسوب مجلد للمؤسسة، يطلب JayV مجلدًا أولًا."$json$::jsonb),
  ('ar', 'docs.organizations.title', $json$"المؤسسات"$json$::jsonb),
  ('ar', 'docs.organizations.summary', $json$"تجمع المؤسسات الأشخاص والمستودعات وسياسة LLM التي يتبعها الفريق كله."$json$::jsonb),
  ('ar', 'docs.organizations.usage', $json$"أنشئ مؤسسة وادعُ الأعضاء من لوحة تحكم موقع JayV. في التطبيق، يفتح Ctrl+2 (⌘2 على Mac) مؤسساتك ومستودعاتها."$json$::jsonb),
  ('ar', 'docs.parallelRequests.title', $json$"الطلبات المتوازية"$json$::jsonb),
  ('ar', 'docs.parallelRequests.summary', $json$"عندما يسمح اشتراكك بأكثر من طلب في الوقت نفسه، تعمل دردشات المشاريع المختلفة معًا، لكل منها وكلاؤها وفهرسها."$json$::jsonb),
  ('ar', 'docs.parallelRequests.usage', $json$"لا شيء لتفعيله: أرسل طلبات في دردشات مشاريع مختلفة ولن ينتظر بعضها بعضًا. تبقى طلبات المشروع الواحد واحدًا تلو الآخر، كي لا يكتب وكيلان في المجلد نفسه أبدًا."$json$::jsonb),
  ('ar', 'docs.parallelTasks.title', $json$"الوكلاء المتوازون"$json$::jsonb),
  ('ar', 'docs.parallelTasks.summary', $json$"يُقسَّم طلب تطوير كبير في مشروع git إلى ما يصل إلى أربعة أجزاء تمس ملفات منفصلة، ينجز كل جزء وكيل مختلف في نسخته الخاصة من المشروع."$json$::jsonb),
  ('ar', 'docs.parallelTasks.usage', $json$"فعّل تقسيم الطلبات الكبيرة بين الوكلاء في الإعدادات › Jev › التوجيه. تعمل الأجزاء معًا في git worktree وتعود التغييرات إلى مجلدك."$json$::jsonb),
  ('ar', 'docs.planFirst.title', $json$"التخطيط قبل البناء"$json$::jsonb),
  ('ar', 'docs.planFirst.summary', $json$"في طلب تطوير معقّد، يكتب أقوى نماذج الاستدلال لديك خطة أولًا، ويتلقاها الوكيل المختار للبناء مع الطلب."$json$::jsonb),
  ('ar', 'docs.planFirst.usage', $json$"فعّل التخطيط بنموذج والبناء بآخر في الإعدادات › Jev › التوجيه. تظهر الخطة في لوحة التقدم أثناء كتابتها؛ وإن فشلت، يستمر التطوير كما كان."$json$::jsonb),
  ('ar', 'docs.profilePhoto.title', $json$"صورة الملف الشخصي"$json$::jsonb),
  ('ar', 'docs.profilePhoto.summary', $json$"صورتك الخاصة، يعرضها JayV مهما كانت طريقة تسجيل دخولك — بالبريد الإلكتروني وكلمة المرور أو بأي حساب مرتبط."$json$::jsonb),
  ('ar', 'docs.profilePhoto.usage', $json$"في موقع JayV، افتح لوحة التحكم › الحساب، وانقر الصورة، واختر صورة واضبط القص. يعرضها التطبيق عند تشغيله التالي؛ وإزالتها تعيد صورة حسابك المرتبط."$json$::jsonb),
  ('ar', 'docs.progressPanel.title', $json$"لوحة التقدم"$json$::jsonb),
  ('ar', 'docs.progressPanel.summary', $json$"لوحة بجوار القائمة الجانبية تعرض ما يفعله JayV الآن، خطوة في كل سطر، لتبقى المحادثة بكامل العرض."$json$::jsonb),
  ('ar', 'docs.progressPanel.usage', $json$"تفتح اللوحة تلقائيًا أثناء تشغيل الطلب. اطوِها إلى شريط رفيع عندما لا تحتاجها؛ وفي دردشة المؤسسة تعرض المستودعات أيضًا."$json$::jsonb),
  ('ar', 'docs.projectNotes.title', $json$"ذاكرة المشروع"$json$::jsonb),
  ('ar', 'docs.projectNotes.summary', $json$"ملاحظات قصيرة عن المشروع — كيف يُختبر، وأين توجد الأشياء، وما لا يُمس — يتلقاها الوكيل مرة واحدة في بداية كل جلسة."$json$::jsonb),
  ('ar', 'docs.projectNotes.usage', $json$"في شاشة دردشات المشروع، انقر ذاكرة المشروع واكتب حتى 2200 حرف. تُرفض الأسرار، وتتزامن الملاحظات مع حسابك."$json$::jsonb),
  ('ar', 'docs.secondOpinion.title', $json$"رأي ثانٍ"$json$::jsonb),
  ('ar', 'docs.secondOpinion.summary', $json$"بعد أن يغيّر طلب ما المشروع في وضع التطوير، يقرأ وكيل من مزوّد آخر الفروق دون تعديل أي شيء ويعدّد المشكلات التي يجدها."$json$::jsonb),
  ('ar', 'docs.secondOpinion.usage', $json$"فعّل رأي ثانٍ من وكيل آخر في الإعدادات › Jev › التوجيه. يلزم وكيلان مفعّلان على الأقل؛ تصل الإجابة أولًا وتليها المراجعة في رسالة مستقلة."$json$::jsonb),
  ('ar', 'docs.secretRedaction.title', $json$"إخفاء الأسرار"$json$::jsonb),
  ('ar', 'docs.secretRedaction.summary', $json$"تُستبدل المفاتيح والرموز المميزة وكلمات المرور قبل وصول أي ملف إلى نموذج."$json$::jsonb),
  ('ar', 'docs.secretRedaction.usage', $json$"مفعّل دائمًا في كل الاشتراكات؛ ولا يوجد مفتاح لإيقافه."$json$::jsonb),
  ('ar', 'docs.sensitiveFiles.title', $json$"الملفات المحمية"$json$::jsonb),
  ('ar', 'docs.sensitiveFiles.summary', $json$"ملفات مثل .env والمفاتيح الخاصة والشهادات لا تدخل السياق أبدًا، ولا يستطيع الوكلاء قراءتها أو تعديلها."$json$::jsonb),
  ('ar', 'docs.sensitiveFiles.usage', $json$"تُطبَّق القائمة الافتراضية دائمًا؛ أضف أنماطك في لا تُقرأ أبدًا ضمن الإعدادات › التطبيق. ويمنع Claude Code أيضًا قراءته وتعديله لهذه الملفات، وأي تغيير يجريه وكيل على ملف محمي يُحتجز عند بوابة الخروج."$json$::jsonb),
  ('ar', 'docs.stats.title', $json$"الإحصاءات"$json$::jsonb),
  ('ar', 'docs.stats.summary', $json$"استهلاك الرموز والتكلفة وحصص الوكلاء والرسوم البيانية لكل مشروع ولكل مؤسسة."$json$::jsonb),
  ('ar', 'docs.stats.usage', $json$"افتح الإحصاءات من القائمة الجانبية أو اضغط Ctrl+3 (⌘3 على Mac)."$json$::jsonb),
  ('ar', 'docs.stopRequest.title', $json$"إيقاف طلب"$json$::jsonb),
  ('ar', 'docs.stopRequest.summary', $json$"يمكن إيقاف الطلب الجاري في أي لحظة: يُغلق الوكيل وكل العمليات التي فتحها، ويبقى ما قاله في الدردشة."$json$::jsonb),
  ('ar', 'docs.stopRequest.usage', $json$"أثناء تشغيل الطلب، يتحول زر إرسال إلى إيقاف. ويمكن إزالة الطلب المنتظر في الطابور منه. ويتوقف كل طلب أيضًا عند الحد الزمني المضبوط في الإعدادات › Jev (30 دقيقة افتراضيًا)."$json$::jsonb),
  ('ar', 'docs.symbolIndex.title', $json$"فهرس الرموز لـ Claude"$json$::jsonb),
  ('ar', 'docs.symbolIndex.summary', $json$"يسجّل JayV مكان تعريف كل دالة ونوع وصنف، على حاسوبك ودون إنفاق رموز، ويمكن لـ Claude Code الاستعلام من هذه الخريطة بدل مسح المجلد."$json$::jsonb),
  ('ar', 'docs.symbolIndex.usage', $json$"فعّل أدوات الرموز في JayV في خيارات Claude Code ضمن الإعدادات، عندما يتضمنها اشتراكك. ويُقدَّم الفهرس نفسه لأي وكيل عبر الأمر jayv mcp."$json$::jsonb),
  ('ar', 'docs.twoFactor.title', $json$"المصادقة الثنائية"$json$::jsonb),
  ('ar', 'docs.twoFactor.summary', $json$"إلى جانب كلمة المرور أو الحساب المرتبط، يطلب تسجيل الدخول رمزًا من تطبيق مصادقة على هاتفك."$json$::jsonb),
  ('ar', 'docs.twoFactor.usage', $json$"في موقع JayV، افتح لوحة التحكم › الحساب › الأمان، وامسح رمز QR بتطبيق مصادقة، ثم أكّد بالرمز الأول."$json$::jsonb),
  ('ar', 'docs.updates.title', $json$"التحديثات والجديد"$json$::jsonb),
  ('ar', 'docs.updates.summary', $json$"يبحث JayV عن إصدار جديد في الخلفية، وبعد كل تحديث يعرض ما تغيّر منذ آخر إصدار رأيته."$json$::jsonb),
  ('ar', 'docs.updates.usage', $json$"عند صدور إصدار جديد، يعرض شريط ما الذي يتغير وحدّث الآن. والسجل الكامل في الجديد في JayV ضمن لوحة الأوامر، وفي صفحة ملاحظات الإصدار على الموقع."$json$::jsonb),
  ('ar', 'docs.workModes.title', $json$"أوضاع العمل: تلقائي والتخطيط والتطوير"$json$::jsonb),
  ('ar', 'docs.workModes.summary', $json$"لكل دردشة وضع عمل. التخطيط يقرأ المشروع فقط ويجيب بخطة؛ والتطوير يغيّر الملفات؛ والتلقائي يترك لـ Jev الاختيار في كل طلب."$json$::jsonb),
  ('ar', 'docs.workModes.usage', $json$"اختر الوضع أسفل مربع الرسالة، أو اكتب /plan أو /build أو /auto في بداية الرسالة، أو اضغط Ctrl+. (⌘. على Mac). عندما تطلب دردشة في وضع التخطيط التنفيذ، ينقلها Jev إلى التطوير."$json$::jsonb),
  ('ar', 'docs.command.modeAuto', $json$"يختار Jev التخطيط أو التطوير لكل طلب في هذه الدردشة."$json$::jsonb),
  ('ar', 'docs.command.modePlan', $json$"يضع الدردشة في وضع التخطيط: يقرأ الوكيل فقط ويجيب بخطة. يُرسَل النص الذي يلي الأمر بوصفه الطلب."$json$::jsonb),
  ('ar', 'docs.command.modeBuild', $json$"يضع الدردشة في وضع التطوير: يغيّر الوكيل ملفات المشروع. يُرسَل النص الذي يلي الأمر بوصفه الطلب."$json$::jsonb),
  ('ar', 'docs.command.palette', $json$"يفتح لوحة الأوامر."$json$::jsonb),
  ('ar', 'docs.command.projects', $json$"ينتقل إلى المشاريع."$json$::jsonb),
  ('ar', 'docs.command.organizations', $json$"ينتقل إلى المؤسسات."$json$::jsonb),
  ('ar', 'docs.command.stats', $json$"ينتقل إلى الإحصاءات."$json$::jsonb),
  ('ar', 'docs.command.system', $json$"ينتقل إلى النظام."$json$::jsonb),
  ('ar', 'docs.command.settings', $json$"يفتح الإعدادات."$json$::jsonb),
  ('ar', 'docs.command.newChat', $json$"يبدأ دردشة جديدة في المشروع المفتوح."$json$::jsonb),
  ('ar', 'docs.command.gate', $json$"يفتح بوابة المشروع المفتوح."$json$::jsonb),
  ('ar', 'docs.command.workMode', $json$"يبدّل وضع العمل في الدردشة المفتوحة."$json$::jsonb),
  ('ar', 'docs.command.cliStatus', $json$"يعرض الإصدار وملف الإعدادات وعدد الوكلاء والنماذج القابلة للتشغيل وعدد الملفات المفهرسة."$json$::jsonb),
  ('ar', 'docs.command.cliRun', $json$"يرسل طلبًا واحدًا عبر البوابة والموجّه ويطبع الإجابة."$json$::jsonb),
  ('ar', 'docs.command.cliIndex', $json$"يفهرس مجلد المشروع ويطبع عدد الملفات التي دخلت الفهرس."$json$::jsonb),
  ('ar', 'docs.command.cliVersion', $json$"يطبع الإصدار المثبّت."$json$::jsonb),
  ('ar', 'docs.command.cliBench', $json$"يشغّل ملف مهام عبر JayV ومباشرة عبر الوكيل، كلٌّ في نسخته الخاصة، ويقارن الجولات والتكلفة."$json$::jsonb),
  ('ar', 'docs.command.cliMcp', $json$"يقدّم فهرس رموز المشروع عبر MCP (stdio) لوكلاء البرمجة."$json$::jsonb),
  ('fr', 'docs.adaptiveRouting.title', $json$"Routage adaptatif"$json$::jsonb),
  ('fr', 'docs.adaptiveRouting.summary', $json$"Jev choisit quel agent et quel modèle répondent à chaque demande, en tenant compte des résultats de chaque modèle par type de demande."$json$::jsonb),
  ('fr', 'docs.adaptiveRouting.usage', $json$"Gardez plus d'un agent activé dans Configuration. Une réponse que vous signalez comme n'ayant pas fonctionné, ou que la loge de sortie retient, coûte un point au modèle. Si l'agent choisi est absent ou non connecté, la demande passe au suivant."$json$::jsonb),
  ('fr', 'docs.agentSessions.title', $json$"Sessions de l'agent"$json$::jsonb),
  ('fr', 'docs.agentSessions.summary', $json$"Chaque chat reprend la session de son agent au lieu de relire le projet et toute la conversation à chaque message."$json$::jsonb),
  ('fr', 'docs.agentSessions.usage', $json$"Toujours activé. Une nouvelle session démarre après 10 demandes, ou quand l'agent, le modèle ou le dossier change."$json$::jsonb),
  ('fr', 'docs.agents.title', $json$"Agents en ligne de commande"$json$::jsonb),
  ('fr', 'docs.agents.summary', $json$"JayV n'écrit pas de code lui-même : il orchestre les agents de code que vous utilisez déjà — Codex, Claude Code, GitHub Copilot et Cursor Agent — en lançant la ligne de commande de chacun sur votre ordinateur."$json$::jsonb),
  ('fr', 'docs.agents.usage', $json$"Ouvrez Configuration, activez les agents installés sur cet ordinateur et listez les modèles que chacun peut utiliser. Chaque CLI garde sa propre connexion ; aucune clé ni aucun mot de passe ne passe par JayV. La page Système indique si chaque agent est installé et répond."$json$::jsonb),
  ('fr', 'docs.answerRecall.title', $json$"Réponses précédentes"$json$::jsonb),
  ('fr', 'docs.answerRecall.summary', $json$"Une demande presque identique à une autre déjà traitée dans un autre chat du même projet part de cette réponse au lieu de tout réexplorer."$json$::jsonb),
  ('fr', 'docs.answerRecall.usage', $json$"Fonctionne tout seul quand votre forfait l'inclut. Chaque fois qu'une réponse précédente est réutilisée, le panneau de Jev l'indique."$json$::jsonb),
  ('fr', 'docs.chatSearch.title', $json$"Recherche dans les chats"$json$::jsonb),
  ('fr', 'docs.chatSearch.summary', $json$"Recherchez des mots dans toutes les conversations d'un projet, avec le passage trouvé mis en évidence."$json$::jsonb),
  ('fr', 'docs.chatSearch.usage', $json$"Sur l'écran des chats d'un projet, tapez dans le champ de recherche. L'index reste sur votre ordinateur et la recherche ne passe jamais par le réseau."$json$::jsonb),
  ('fr', 'docs.cli.title', $json$"JayV dans le terminal"$json$::jsonb),
  ('fr', 'docs.cli.summary', $json$"Le même orchestrateur fonctionne depuis un terminal, avec les agents et les modèles configurés dans l'application."$json$::jsonb),
  ('fr', 'docs.cli.usage', $json$"Lancez jayv suivi d'une commande dans le dossier du projet, ou passez le dossier avec --root. --config pointe vers un autre fichier de configuration."$json$::jsonb),
  ('fr', 'docs.commandPalette.title', $json$"Palette de commandes et raccourcis"$json$::jsonb),
  ('fr', 'docs.commandPalette.summary', $json$"Tout ce qui a un bouton a aussi un nom dans la palette de commandes, et les écrans principaux ont des raccourcis clavier."$json$::jsonb),
  ('fr', 'docs.commandPalette.usage', $json$"Appuyez sur Ctrl+K (⌘K sur Mac) sur n'importe quel écran et tapez : aller à une page, ouvrir un projet, un chat ou une organisation, démarrer un chat ou changer de thème."$json$::jsonb),
  ('fr', 'docs.contextCache.title', $json$"Cache du contexte"$json$::jsonb),
  ('fr', 'docs.contextCache.summary', $json$"Le contexte construit pour une demande est réutilisé pendant au moins cinq minutes tant que les fichiers ne changent pas, ainsi la demande suivante ne refait pas la recherche dans le projet."$json$::jsonb),
  ('fr', 'docs.contextCache.usage', $json$"Toujours activé. Modifier un fichier du projet ne rafraîchit que ce qui a changé."$json$::jsonb),
  ('fr', 'docs.entryGate.title', $json$"Loge d'entrée"$json$::jsonb),
  ('fr', 'docs.entryGate.summary', $json$"Jev vérifie chaque demande avant qu'un agent ne se lance : ce qu'elle demande, où elle s'applique et ce qui manque."$json$::jsonb),
  ('fr', 'docs.entryGate.usage', $json$"Toujours activée. Quand il manque quelque chose, la loge l'indique et propose d'envoyer tel quel, d'envoyer la version réécrite par JayV ou de compléter la demande."$json$::jsonb),
  ('fr', 'docs.exitGate.title', $json$"Loge de sortie"$json$::jsonb),
  ('fr', 'docs.exitGate.summary', $json$"Jev vérifie les commandes et les fichiers de chaque réponse au regard des règles du projet avant que vous n'agissiez dessus."$json$::jsonb),
  ('fr', 'docs.exitGate.usage', $json$"Toujours activée. Une réponse qui touche un fichier protégé ou lance une commande interdite est retenue, et la loge explique pourquoi."$json$::jsonb),
  ('fr', 'docs.gateBoard.title', $json$"Tableau de la loge"$json$::jsonb),
  ('fr', 'docs.gateBoard.summary', $json$"Une page avec tout ce que Jev a laissé passer, demandé ou bloqué dans le projet."$json$::jsonb),
  ('fr', 'docs.gateBoard.usage', $json$"Ouvrez-la depuis le menu latéral, depuis le compteur de la barre d'état ou avec Ctrl+G (⌘G sur Mac). Les réponses que vous donnez à la loge deviennent des notes du projet, et elle ne repose plus la question."$json$::jsonb),
  ('fr', 'docs.leanCode.title', $json$"Code concis"$json$::jsonb),
  ('fr', 'docs.leanCode.summary', $json$"En mode développement, l'agent écrit le minimum de code qui résout la tâche et réutilise ce que le langage, la plateforme ou une bibliothèque installée font déjà."$json$::jsonb),
  ('fr', 'docs.leanCode.usage', $json$"Activé par défaut. La validation, la gestion des erreurs, la sécurité et l'accessibilité ne sont jamais sacrifiées. Désactivez-le dans Votre niveau, sur la page Profil."$json$::jsonb),
  ('fr', 'docs.liveFiles.title', $json$"Fichiers en direct"$json$::jsonb),
  ('fr', 'docs.liveFiles.summary', $json$"Un panneau à côté de la conversation affiche chaque fichier modifié par la demande, du plus récent au plus ancien, avec le diff de chacun pendant que l'agent écrit."$json$::jsonb),
  ('fr', 'docs.liveFiles.usage', $json$"Cliquez sur En direct dans l'en-tête du chat ; il s'ouvre aussi tout seul au premier changement. Suivez l'agent pour voir chaque fichier dès qu'il change."$json$::jsonb),
  ('fr', 'docs.orgChat.title', $json$"Chat de l'organisation"$json$::jsonb),
  ('fr', 'docs.orgChat.summary', $json$"Un chat qui travaille sur tous les dépôts d'une organisation à la fois, avec l'agent, l'index et la loge qui les voient tous."$json$::jsonb),
  ('fr', 'docs.orgChat.usage', $json$"Sur la page de l'organisation, cliquez sur Chat de l'organisation. Sans dossier de l'organisation sur cet ordinateur, JayV vous en demande un d'abord."$json$::jsonb),
  ('fr', 'docs.organizations.title', $json$"Organisations"$json$::jsonb),
  ('fr', 'docs.organizations.summary', $json$"Les organisations regroupent des personnes, des dépôts et la politique de LLM que suit toute l'équipe."$json$::jsonb),
  ('fr', 'docs.organizations.usage', $json$"Créez une organisation et invitez des membres dans le tableau de bord du site de JayV. Dans l'application, Ctrl+2 (⌘2 sur Mac) ouvre vos organisations et leurs dépôts."$json$::jsonb),
  ('fr', 'docs.parallelRequests.title', $json$"Demandes en parallèle"$json$::jsonb),
  ('fr', 'docs.parallelRequests.summary', $json$"Quand votre forfait autorise plusieurs demandes à la fois, les chats de projets différents s'exécutent en même temps, chacun avec ses propres agents et son propre index."$json$::jsonb),
  ('fr', 'docs.parallelRequests.usage', $json$"Rien à activer : envoyez des demandes dans des chats de projets différents et elles ne s'attendent plus. Les demandes d'un même projet passent toujours une par une, pour que deux agents n'écrivent jamais dans le même dossier."$json$::jsonb),
  ('fr', 'docs.parallelTasks.title', $json$"Agents en parallèle"$json$::jsonb),
  ('fr', 'docs.parallelTasks.summary', $json$"Une grosse demande de développement dans un projet git est divisée en jusqu'à quatre parties qui touchent des fichiers distincts, chacune réalisée par un agent différent dans sa propre copie du projet."$json$::jsonb),
  ('fr', 'docs.parallelTasks.usage', $json$"Activez Répartir les grosses demandes entre agents dans Configuration › Jev › Routage. Les parties s'exécutent en même temps dans des git worktrees et les changements reviennent dans votre dossier."$json$::jsonb),
  ('fr', 'docs.planFirst.title', $json$"Planifier avant de construire"$json$::jsonb),
  ('fr', 'docs.planFirst.summary', $json$"Pour une demande de développement complexe, votre modèle de raisonnement le plus puissant écrit d'abord un plan, et l'agent choisi pour construire le reçoit avec la demande."$json$::jsonb),
  ('fr', 'docs.planFirst.usage', $json$"Activez Planifier avec un modèle, construire avec un autre dans Configuration › Jev › Routage. Le plan s'affiche dans le panneau d'avancement pendant qu'il s'écrit ; s'il échoue, le développement continue comme avant."$json$::jsonb),
  ('fr', 'docs.profilePhoto.title', $json$"Photo de profil"$json$::jsonb),
  ('fr', 'docs.profilePhoto.summary', $json$"Votre propre photo, affichée dans JayV quelle que soit votre façon de vous connecter : e-mail et mot de passe ou n'importe quel compte associé."$json$::jsonb),
  ('fr', 'docs.profilePhoto.usage', $json$"Sur le site de JayV, ouvrez Tableau de bord › Compte, cliquez sur la photo, choisissez une image et ajustez le recadrage. L'application l'affiche à son prochain démarrage ; la supprimer fait revenir la photo de votre compte associé."$json$::jsonb),
  ('fr', 'docs.progressPanel.title', $json$"Panneau d'avancement"$json$::jsonb),
  ('fr', 'docs.progressPanel.summary', $json$"Un panneau à côté du menu latéral montre ce que JayV fait en ce moment, une étape par ligne, pour que la conversation garde toute la largeur."$json$::jsonb),
  ('fr', 'docs.progressPanel.usage', $json$"Le panneau s'ouvre tout seul pendant qu'une demande s'exécute. Réduisez-le à une fine bande quand vous n'en avez pas besoin ; dans un chat de l'organisation, il liste aussi les dépôts."$json$::jsonb),
  ('fr', 'docs.projectNotes.title', $json$"Mémoire du projet"$json$::jsonb),
  ('fr', 'docs.projectNotes.summary', $json$"De courtes notes sur le projet — comment tester, où se trouvent les choses, ce qu'il ne faut pas toucher — que l'agent reçoit une fois, au début de chaque session."$json$::jsonb),
  ('fr', 'docs.projectNotes.usage', $json$"Sur l'écran des chats d'un projet, cliquez sur Mémoire du projet et écrivez jusqu'à 2 200 caractères. Les secrets sont refusés, et les notes se synchronisent avec votre compte."$json$::jsonb),
  ('fr', 'docs.secondOpinion.title', $json$"Deuxième avis"$json$::jsonb),
  ('fr', 'docs.secondOpinion.summary', $json$"Après qu'une demande a modifié le projet en mode développement, un agent d'un autre fournisseur lit le diff sans rien modifier et liste les problèmes qu'il trouve."$json$::jsonb),
  ('fr', 'docs.secondOpinion.usage', $json$"Activez Deuxième avis d’un autre agent dans Configuration › Jev › Routage. Il faut au moins deux agents activés ; la réponse arrive d'abord et la revue suit dans son propre message."$json$::jsonb),
  ('fr', 'docs.secretRedaction.title', $json$"Masquage des secrets"$json$::jsonb),
  ('fr', 'docs.secretRedaction.summary', $json$"Les clés, jetons et mots de passe sont remplacés avant qu'un fichier n'atteigne un modèle."$json$::jsonb),
  ('fr', 'docs.secretRedaction.usage', $json$"Toujours activé, dans tous les forfaits ; aucun interrupteur ne permet de le désactiver."$json$::jsonb),
  ('fr', 'docs.sensitiveFiles.title', $json$"Fichiers protégés"$json$::jsonb),
  ('fr', 'docs.sensitiveFiles.summary', $json$"Les fichiers comme .env, les clés privées et les certificats n'entrent jamais dans le contexte, et les agents ne peuvent ni les lire ni les modifier."$json$::jsonb),
  ('fr', 'docs.sensitiveFiles.usage', $json$"La liste par défaut s'applique toujours ; ajoutez vos propres motifs dans Ne jamais lire, sous Configuration › Application. Claude Code bloque aussi ses propres lectures et modifications de ces fichiers, et tout changement d'un agent sur un fichier protégé est retenu à la loge de sortie."$json$::jsonb),
  ('fr', 'docs.stats.title', $json$"Statistiques"$json$::jsonb),
  ('fr', 'docs.stats.summary', $json$"Consommation de jetons, coût, quotas des agents et graphiques par projet et par organisation."$json$::jsonb),
  ('fr', 'docs.stats.usage', $json$"Ouvrez Statistiques depuis le menu latéral ou appuyez sur Ctrl+3 (⌘3 sur Mac)."$json$::jsonb),
  ('fr', 'docs.stopRequest.title', $json$"Arrêter une demande"$json$::jsonb),
  ('fr', 'docs.stopRequest.summary', $json$"Une demande en cours peut être arrêtée à tout moment : l'agent et tous les processus qu'il a ouverts sont fermés, et ce qu'il a déjà dit reste dans le chat."$json$::jsonb),
  ('fr', 'docs.stopRequest.usage', $json$"Pendant qu'une demande s'exécute, le bouton Envoyer devient Arrêter. Une demande en attente dans la file peut en être retirée. Toute demande s'arrête aussi à la limite de temps définie dans Configuration › Jev (30 minutes par défaut)."$json$::jsonb),
  ('fr', 'docs.symbolIndex.title', $json$"Index des symboles pour Claude"$json$::jsonb),
  ('fr', 'docs.symbolIndex.summary', $json$"JayV repère où chaque fonction, type et classe est défini, sur votre ordinateur et sans dépenser de jetons, et Claude Code peut interroger cette carte au lieu de parcourir le dossier."$json$::jsonb),
  ('fr', 'docs.symbolIndex.usage', $json$"Activez Outils de symboles de JayV dans les options de Claude Code, dans Configuration, quand votre forfait l'inclut. Le même index est servi à n'importe quel agent par la commande jayv mcp."$json$::jsonb),
  ('fr', 'docs.twoFactor.title', $json$"Authentification à deux facteurs"$json$::jsonb),
  ('fr', 'docs.twoFactor.summary', $json$"En plus du mot de passe ou du compte associé, la connexion demande un code d'une application d'authentification sur votre téléphone."$json$::jsonb),
  ('fr', 'docs.twoFactor.usage', $json$"Sur le site de JayV, ouvrez Tableau de bord › Compte › Sécurité, scannez le QR code avec une application d'authentification et confirmez avec le premier code."$json$::jsonb),
  ('fr', 'docs.updates.title', $json$"Mises à jour et nouveautés"$json$::jsonb),
  ('fr', 'docs.updates.summary', $json$"JayV recherche une nouvelle version en arrière-plan et, après chaque mise à jour, montre ce qui a changé depuis la dernière version que vous avez vue."$json$::jsonb),
  ('fr', 'docs.updates.usage', $json$"Quand une nouvelle version sort, une barre propose Ce qui change et Mettre à jour maintenant. L'historique complet se trouve dans Nouveautés de JayV, dans la palette de commandes, et sur la page Notes de version du site."$json$::jsonb),
  ('fr', 'docs.workModes.title', $json$"Modes de travail : Auto, Planification et Développement"$json$::jsonb),
  ('fr', 'docs.workModes.summary', $json$"Chaque chat a un mode de travail. Planification ne fait que lire le projet et répond par un plan ; Développement modifie des fichiers ; Auto laisse Jev choisir à chaque demande."$json$::jsonb),
  ('fr', 'docs.workModes.usage', $json$"Choisissez le mode sous la zone de message, tapez /plan, /build ou /auto au début d'un message, ou appuyez sur Ctrl+. (⌘. sur Mac). Quand un chat en Planification demande d'implémenter, Jev le passe en Développement."$json$::jsonb),
  ('fr', 'docs.command.modeAuto', $json$"Jev choisit planification ou développement pour chaque demande de ce chat."$json$::jsonb),
  ('fr', 'docs.command.modePlan', $json$"Passe le chat en Planification : l'agent ne fait que lire et répond par un plan. Le texte après la commande est envoyé comme demande."$json$::jsonb),
  ('fr', 'docs.command.modeBuild', $json$"Passe le chat en Développement : l'agent modifie des fichiers du projet. Le texte après la commande est envoyé comme demande."$json$::jsonb),
  ('fr', 'docs.command.palette', $json$"Ouvre la palette de commandes."$json$::jsonb),
  ('fr', 'docs.command.projects', $json$"Va à Projets."$json$::jsonb),
  ('fr', 'docs.command.organizations', $json$"Va à Organisations."$json$::jsonb),
  ('fr', 'docs.command.stats', $json$"Va à Statistiques."$json$::jsonb),
  ('fr', 'docs.command.system', $json$"Va à Système."$json$::jsonb),
  ('fr', 'docs.command.settings', $json$"Ouvre Configuration."$json$::jsonb),
  ('fr', 'docs.command.newChat', $json$"Démarre un nouveau chat dans le projet ouvert."$json$::jsonb),
  ('fr', 'docs.command.gate', $json$"Ouvre la loge du projet ouvert."$json$::jsonb),
  ('fr', 'docs.command.workMode', $json$"Change le mode de travail du chat ouvert."$json$::jsonb),
  ('fr', 'docs.command.cliStatus', $json$"Affiche la version, le fichier de configuration, le nombre d'agents et de modèles utilisables et le nombre de fichiers indexés."$json$::jsonb),
  ('fr', 'docs.command.cliRun', $json$"Envoie une demande à travers la loge et le routeur et affiche la réponse."$json$::jsonb),
  ('fr', 'docs.command.cliIndex', $json$"Indexe le dossier du projet et affiche le nombre de fichiers ajoutés."$json$::jsonb),
  ('fr', 'docs.command.cliVersion', $json$"Affiche la version installée."$json$::jsonb),
  ('fr', 'docs.command.cliBench', $json$"Exécute un fichier de tâches via JayV et directement dans l'agent, chacun dans sa propre copie, et compare les tours et le coût."$json$::jsonb),
  ('fr', 'docs.command.cliMcp', $json$"Sert l'index des symboles du projet via MCP (stdio) pour les agents de code."$json$::jsonb),
  ('ru', 'docs.adaptiveRouting.title', $json$"Адаптивная маршрутизация"$json$::jsonb),
  ('ru', 'docs.adaptiveRouting.summary', $json$"Jev выбирает, какой агент и какая модель отвечают на каждый запрос, учитывая результаты каждой модели по типу запроса."$json$::jsonb),
  ('ru', 'docs.adaptiveRouting.usage', $json$"Держите в настройках включёнными больше одного агента. Ответ, который вы отметили как неработающий или который задержала выходная проходная, стоит модели одного очка. Если выбранного агента нет или он не вошёл в аккаунт, запрос переходит к следующему."$json$::jsonb),
  ('ru', 'docs.agentSessions.title', $json$"Сессии агента"$json$::jsonb),
  ('ru', 'docs.agentSessions.summary', $json$"Каждый чат продолжает сессию своего агента, а не перечитывает проект и весь разговор при каждом сообщении."$json$::jsonb),
  ('ru', 'docs.agentSessions.usage', $json$"Всегда включено. Новая сессия начинается после 10 запросов или когда меняются агент, модель или папка."$json$::jsonb),
  ('ru', 'docs.agents.title', $json$"Агенты командной строки"$json$::jsonb),
  ('ru', 'docs.agents.summary', $json$"JayV сам не пишет код: он управляет агентами, которыми вы уже пользуетесь, — Codex, Claude Code, GitHub Copilot и Cursor Agent, — запуская командную строку каждого на вашем компьютере."$json$::jsonb),
  ('ru', 'docs.agents.usage', $json$"Откройте настройки, включите агентов, установленных на этом компьютере, и перечислите модели, которые может использовать каждый. Каждая CLI хранит собственный вход; ни ключи, ни пароли не проходят через JayV. Страница «Система» показывает, установлен ли каждый агент и отвечает ли он."$json$::jsonb),
  ('ru', 'docs.answerRecall.title', $json$"Прежние ответы"$json$::jsonb),
  ('ru', 'docs.answerRecall.summary', $json$"Запрос, почти совпадающий с уже отвеченным в другом чате того же проекта, начинается с того ответа, а не исследует всё заново."$json$::jsonb),
  ('ru', 'docs.answerRecall.usage', $json$"Работает само, если это входит в ваш тариф. Каждый раз, когда прежний ответ используется повторно, это видно на панели Jev."$json$::jsonb),
  ('ru', 'docs.chatSearch.title', $json$"Поиск по чатам"$json$::jsonb),
  ('ru', 'docs.chatSearch.summary', $json$"Ищите слова во всех разговорах проекта с подсветкой найденного фрагмента."$json$::jsonb),
  ('ru', 'docs.chatSearch.usage', $json$"На экране чатов проекта введите текст в поле поиска. Индекс хранится на вашем компьютере, и поиск никогда не уходит в сеть."$json$::jsonb),
  ('ru', 'docs.cli.title', $json$"JayV в терминале"$json$::jsonb),
  ('ru', 'docs.cli.summary', $json$"Тот же оркестратор работает из терминала, с агентами и моделями, настроенными в приложении."$json$::jsonb),
  ('ru', 'docs.cli.usage', $json$"Запустите jayv с командой в папке проекта или укажите папку через --root. --config указывает на другой файл конфигурации."$json$::jsonb),
  ('ru', 'docs.commandPalette.title', $json$"Палитра команд и сочетания клавиш"$json$::jsonb),
  ('ru', 'docs.commandPalette.summary', $json$"У всего, что имеет кнопку, есть и название в палитре команд, а у основных экранов есть сочетания клавиш."$json$::jsonb),
  ('ru', 'docs.commandPalette.usage', $json$"Нажмите Ctrl+K (⌘K на Mac) на любом экране и введите: перейти на страницу, открыть проект, чат или организацию, начать чат или сменить тему."$json$::jsonb),
  ('ru', 'docs.contextCache.title', $json$"Кэш контекста"$json$::jsonb),
  ('ru', 'docs.contextCache.summary', $json$"Контекст, собранный для запроса, используется повторно не менее пяти минут, пока файлы не меняются, поэтому следующий запрос не ищет по проекту заново."$json$::jsonb),
  ('ru', 'docs.contextCache.usage', $json$"Всегда включён. При изменении файла в проекте обновляется только изменившееся."$json$::jsonb),
  ('ru', 'docs.entryGate.title', $json$"Входная проходная"$json$::jsonb),
  ('ru', 'docs.entryGate.summary', $json$"Jev проверяет каждый запрос до запуска любого агента: что он просит, к чему относится и чего не хватает."$json$::jsonb),
  ('ru', 'docs.entryGate.usage', $json$"Всегда включена. Когда чего-то не хватает, проходная показывает это и предлагает отправить как есть, отправить версию, переписанную JayV, или дополнить запрос."$json$::jsonb),
  ('ru', 'docs.exitGate.title', $json$"Выходная проходная"$json$::jsonb),
  ('ru', 'docs.exitGate.summary', $json$"Jev сверяет команды и файлы каждого ответа с правилами проекта до того, как вы начнёте действовать."$json$::jsonb),
  ('ru', 'docs.exitGate.usage', $json$"Всегда включена. Ответ, который затрагивает защищённый файл или запускает запрещённую команду, задерживается, и проходная объясняет почему."$json$::jsonb),
  ('ru', 'docs.gateBoard.title', $json$"Панель проходной"$json$::jsonb),
  ('ru', 'docs.gateBoard.summary', $json$"Одна страница со всем, что Jev пропустил, уточнил или заблокировал в проекте."$json$::jsonb),
  ('ru', 'docs.gateBoard.usage', $json$"Откройте её из бокового меню, по счётчику в строке состояния или сочетанием Ctrl+G (⌘G на Mac). Ваши ответы проходной становятся заметками проекта, и она больше не спрашивает об этом."$json$::jsonb),
  ('ru', 'docs.leanCode.title', $json$"Компактный код"$json$::jsonb),
  ('ru', 'docs.leanCode.summary', $json$"В режиме разработки агент пишет минимум кода, решающего задачу, и использует то, что уже умеют язык, платформа или установленная библиотека."$json$::jsonb),
  ('ru', 'docs.leanCode.usage', $json$"Включено по умолчанию. Проверка данных, обработка ошибок, безопасность и доступность никогда не урезаются. Отключается в разделе «Ваш уровень» на странице «Профиль»."$json$::jsonb),
  ('ru', 'docs.liveFiles.title', $json$"Файлы в реальном времени"$json$::jsonb),
  ('ru', 'docs.liveFiles.summary', $json$"Панель рядом с разговором показывает каждый файл, который меняет запрос, от новых к старым, с diff каждого, пока агент пишет."$json$::jsonb),
  ('ru', 'docs.liveFiles.usage', $json$"Нажмите «В реальном времени» в заголовке чата; панель также открывается сама при первом изменении. Следуйте за агентом, чтобы видеть каждый файл сразу после изменения."$json$::jsonb),
  ('ru', 'docs.orgChat.title', $json$"Чат организации"$json$::jsonb),
  ('ru', 'docs.orgChat.summary', $json$"Один чат, который работает сразу со всеми репозиториями организации, причём агент, индекс и проходная видят их все."$json$::jsonb),
  ('ru', 'docs.orgChat.usage', $json$"На странице организации нажмите «Чат организации». Если на этом компьютере нет папки организации, JayV сначала попросит её указать."$json$::jsonb),
  ('ru', 'docs.organizations.title', $json$"Организации"$json$::jsonb),
  ('ru', 'docs.organizations.summary', $json$"Организации объединяют людей, репозитории и политику LLM, которой следует вся команда."$json$::jsonb),
  ('ru', 'docs.organizations.usage', $json$"Создайте организацию и пригласите участников в панели сайта JayV. В приложении Ctrl+2 (⌘2 на Mac) открывает ваши организации и их репозитории."$json$::jsonb),
  ('ru', 'docs.parallelRequests.title', $json$"Параллельные запросы"$json$::jsonb),
  ('ru', 'docs.parallelRequests.summary', $json$"Если тариф допускает несколько запросов одновременно, чаты разных проектов работают параллельно, каждый со своими агентами и индексом."$json$::jsonb),
  ('ru', 'docs.parallelRequests.usage', $json$"Ничего включать не нужно: отправляйте запросы в чатах разных проектов, и они больше не ждут друг друга. Запросы одного проекта по-прежнему идут по одному, чтобы два агента никогда не писали в одну папку."$json$::jsonb),
  ('ru', 'docs.parallelTasks.title', $json$"Параллельные агенты"$json$::jsonb),
  ('ru', 'docs.parallelTasks.summary', $json$"Большой запрос на разработку в git-проекте делится на части (до четырёх) с разными файлами, и каждую выполняет отдельный агент в своей копии проекта."$json$::jsonb),
  ('ru', 'docs.parallelTasks.usage', $json$"Включите «Делить большие запросы между агентами» в разделе Настройки › Jev › Маршрутизация. Части выполняются одновременно в git worktree, а изменения возвращаются в вашу папку."$json$::jsonb),
  ('ru', 'docs.planFirst.title', $json$"Сначала план, потом разработка"$json$::jsonb),
  ('ru', 'docs.planFirst.summary', $json$"Для сложного запроса на разработку ваша самая сильная модель рассуждений сначала пишет план, а агент, выбранный для разработки, получает его вместе с запросом."$json$::jsonb),
  ('ru', 'docs.planFirst.usage', $json$"Включите «Планировать одной моделью, строить другой» в разделе Настройки › Jev › Маршрутизация. План появляется на панели хода работы по мере написания; если он не удался, разработка идёт как раньше."$json$::jsonb),
  ('ru', 'docs.profilePhoto.title', $json$"Фото профиля"$json$::jsonb),
  ('ru', 'docs.profilePhoto.summary', $json$"Ваше собственное фото, которое JayV показывает при любом способе входа — по почте и паролю или через любой привязанный аккаунт."$json$::jsonb),
  ('ru', 'docs.profilePhoto.usage', $json$"На сайте JayV откройте Панель › Аккаунт, нажмите на фото, выберите изображение и настройте кадрирование. Приложение покажет его при следующем запуске; если удалить фото, вернётся фото привязанного аккаунта."$json$::jsonb),
  ('ru', 'docs.progressPanel.title', $json$"Панель хода работы"$json$::jsonb),
  ('ru', 'docs.progressPanel.summary', $json$"Панель рядом с боковым меню показывает, что JayV делает сейчас, по шагу в строке, чтобы разговор занимал всю ширину."$json$::jsonb),
  ('ru', 'docs.progressPanel.usage', $json$"Панель открывается сама, пока выполняется запрос. Сверните её в узкую полосу, когда она не нужна; в чате организации она также показывает репозитории."$json$::jsonb),
  ('ru', 'docs.projectNotes.title', $json$"Память проекта"$json$::jsonb),
  ('ru', 'docs.projectNotes.summary', $json$"Короткие заметки о проекте — как тестировать, где что лежит, чего не трогать, — которые агент получает один раз в начале каждой сессии."$json$::jsonb),
  ('ru', 'docs.projectNotes.usage', $json$"На экране чатов проекта нажмите «Память проекта» и напишите до 2200 символов. Секреты отклоняются, а заметки синхронизируются с вашим аккаунтом."$json$::jsonb),
  ('ru', 'docs.secondOpinion.title', $json$"Второе мнение"$json$::jsonb),
  ('ru', 'docs.secondOpinion.summary', $json$"После того как запрос изменил проект в режиме разработки, агент другого провайдера читает diff, ничего не редактируя, и перечисляет найденные проблемы."$json$::jsonb),
  ('ru', 'docs.secondOpinion.usage', $json$"Включите «Второе мнение другого агента» в разделе Настройки › Jev › Маршрутизация. Нужны как минимум два включённых агента; сначала приходит ответ, а проверка следует отдельным сообщением."$json$::jsonb),
  ('ru', 'docs.secretRedaction.title', $json$"Скрытие секретов"$json$::jsonb),
  ('ru', 'docs.secretRedaction.summary', $json$"Ключи, токены и пароли заменяются до того, как любой файл попадёт к модели."$json$::jsonb),
  ('ru', 'docs.secretRedaction.usage', $json$"Всегда включено во всех тарифах; переключателя для отключения нет."$json$::jsonb),
  ('ru', 'docs.sensitiveFiles.title', $json$"Защищённые файлы"$json$::jsonb),
  ('ru', 'docs.sensitiveFiles.summary', $json$"Такие файлы, как .env, закрытые ключи и сертификаты, никогда не попадают в контекст, и агенты не могут их читать или редактировать."$json$::jsonb),
  ('ru', 'docs.sensitiveFiles.usage', $json$"Стандартный список действует всегда; добавьте свои шаблоны в «Никогда не читать» в разделе Настройки › Приложение. Claude Code также блокирует собственное чтение и правку этих файлов, а любое изменение защищённого файла агентом задерживается на выходной проходной."$json$::jsonb),
  ('ru', 'docs.stats.title', $json$"Статистика"$json$::jsonb),
  ('ru', 'docs.stats.summary', $json$"Расход токенов, стоимость, лимиты агентов и графики по проектам и организациям."$json$::jsonb),
  ('ru', 'docs.stats.usage', $json$"Откройте «Статистику» из бокового меню или нажмите Ctrl+3 (⌘3 на Mac)."$json$::jsonb),
  ('ru', 'docs.stopRequest.title', $json$"Остановка запроса"$json$::jsonb),
  ('ru', 'docs.stopRequest.summary', $json$"Выполняющийся запрос можно остановить в любой момент: агент и все открытые им процессы закрываются, а то, что он уже написал, остаётся в чате."$json$::jsonb),
  ('ru', 'docs.stopRequest.usage', $json$"Пока запрос выполняется, кнопка «Отправить» превращается в «Остановить». Запрос, ожидающий в очереди, можно из неё убрать. Каждый запрос также останавливается по лимиту времени из раздела Настройки › Jev (по умолчанию 30 минут)."$json$::jsonb),
  ('ru', 'docs.symbolIndex.title', $json$"Индекс символов для Claude"$json$::jsonb),
  ('ru', 'docs.symbolIndex.summary', $json$"JayV отмечает, где определены все функции, типы и классы, прямо на вашем компьютере и без расхода токенов, и Claude Code может обращаться к этой карте вместо обхода папки."$json$::jsonb),
  ('ru', 'docs.symbolIndex.usage', $json$"Включите «Инструменты символов JayV» в параметрах Claude Code в настройках, если это входит в ваш тариф. Тот же индекс доступен любому агенту через команду jayv mcp."$json$::jsonb),
  ('ru', 'docs.twoFactor.title', $json$"Двухфакторная аутентификация"$json$::jsonb),
  ('ru', 'docs.twoFactor.summary', $json$"Помимо пароля или привязанного аккаунта, для входа нужен код из приложения-аутентификатора на телефоне."$json$::jsonb),
  ('ru', 'docs.twoFactor.usage', $json$"На сайте JayV откройте Панель › Аккаунт › Безопасность, отсканируйте QR-код приложением-аутентификатором и подтвердите первым кодом."$json$::jsonb),
  ('ru', 'docs.updates.title', $json$"Обновления и новинки"$json$::jsonb),
  ('ru', 'docs.updates.summary', $json$"JayV проверяет новые версии в фоне и после каждого обновления показывает, что изменилось со времени последней просмотренной версии."$json$::jsonb),
  ('ru', 'docs.updates.usage', $json$"Когда выходит новая версия, панель предлагает «Что меняется» и «Обновить сейчас». Полная история — в пункте «Что нового в JayV» палитры команд и на странице «Примечания к версиям» на сайте."$json$::jsonb),
  ('ru', 'docs.workModes.title', $json$"Режимы работы: Авто, Планирование и Разработка"$json$::jsonb),
  ('ru', 'docs.workModes.summary', $json$"У каждого чата есть режим работы. Планирование только читает проект и отвечает планом; Разработка меняет файлы; Авто позволяет Jev выбирать для каждого запроса."$json$::jsonb),
  ('ru', 'docs.workModes.usage', $json$"Выберите режим под полем сообщения, введите /plan, /build или /auto в начале сообщения или нажмите Ctrl+. (⌘. на Mac). Когда в чате в режиме Планирования просят реализовать, Jev переключает его на Разработку."$json$::jsonb),
  ('ru', 'docs.command.modeAuto', $json$"Jev выбирает планирование или разработку для каждого запроса в этом чате."$json$::jsonb),
  ('ru', 'docs.command.modePlan', $json$"Переводит чат в Планирование: агент только читает и отвечает планом. Текст после команды отправляется как запрос."$json$::jsonb),
  ('ru', 'docs.command.modeBuild', $json$"Переводит чат в Разработку: агент меняет файлы проекта. Текст после команды отправляется как запрос."$json$::jsonb),
  ('ru', 'docs.command.palette', $json$"Открывает палитру команд."$json$::jsonb),
  ('ru', 'docs.command.projects', $json$"Переходит в «Проекты»."$json$::jsonb),
  ('ru', 'docs.command.organizations', $json$"Переходит в «Организации»."$json$::jsonb),
  ('ru', 'docs.command.stats', $json$"Переходит в «Статистику»."$json$::jsonb),
  ('ru', 'docs.command.system', $json$"Переходит в «Систему»."$json$::jsonb),
  ('ru', 'docs.command.settings', $json$"Открывает настройки."$json$::jsonb),
  ('ru', 'docs.command.newChat', $json$"Начинает новый чат в открытом проекте."$json$::jsonb),
  ('ru', 'docs.command.gate', $json$"Открывает проходную открытого проекта."$json$::jsonb),
  ('ru', 'docs.command.workMode', $json$"Переключает режим работы открытого чата."$json$::jsonb),
  ('ru', 'docs.command.cliStatus', $json$"Показывает версию, файл конфигурации, сколько агентов и моделей могут работать и сколько файлов проиндексировано."$json$::jsonb),
  ('ru', 'docs.command.cliRun', $json$"Отправляет один запрос через проходную и маршрутизатор и выводит ответ."$json$::jsonb),
  ('ru', 'docs.command.cliIndex', $json$"Индексирует папку проекта и выводит, сколько файлов попало в индекс."$json$::jsonb),
  ('ru', 'docs.command.cliVersion', $json$"Выводит установленную версию."$json$::jsonb),
  ('ru', 'docs.command.cliBench', $json$"Прогоняет файл задач через JayV и напрямую через агента, каждый в своей копии, и сравнивает раунды и стоимость."$json$::jsonb),
  ('ru', 'docs.command.cliMcp', $json$"Отдаёт индекс символов проекта по MCP (stdio) для агентов программирования."$json$::jsonb),
  ('ja', 'docs.adaptiveRouting.title', $json$"アダプティブルーティング"$json$::jsonb),
  ('ja', 'docs.adaptiveRouting.summary', $json$"Jev は、依頼の種類ごとの各モデルの実績をもとに、どのエージェントとモデルが各依頼に答えるかを選びます。"$json$::jsonb),
  ('ja', 'docs.adaptiveRouting.usage', $json$"設定で複数のエージェントを有効にしておきます。うまくいかなかったと伝えた回答や、出口ゲートが保留した回答は、そのモデルの点数を 1 点下げます。選ばれたエージェントが見つからないかログインしていない場合、依頼は次のエージェントに回ります。"$json$::jsonb),
  ('ja', 'docs.agentSessions.title', $json$"エージェントのセッション"$json$::jsonb),
  ('ja', 'docs.agentSessions.summary', $json$"各チャットは、メッセージのたびにプロジェクトと会話全体を読み直すのではなく、エージェントのセッションを再開します。"$json$::jsonb),
  ('ja', 'docs.agentSessions.usage', $json$"常に有効です。10 件の依頼の後、またはエージェント・モデル・フォルダーが変わったときに新しいセッションが始まります。"$json$::jsonb),
  ('ja', 'docs.agents.title', $json$"コマンドラインエージェント"$json$::jsonb),
  ('ja', 'docs.agents.summary', $json$"JayV 自体はコードを書きません。普段お使いのコーディングエージェント（Codex、Claude Code、GitHub Copilot、Cursor Agent）を、あなたのコンピューターでそれぞれのコマンドラインを動かしてまとめます。"$json$::jsonb),
  ('ja', 'docs.agents.usage', $json$"設定を開き、このコンピューターにインストールされているエージェントを有効にして、それぞれが使えるモデルを登録します。各 CLI はそれぞれのログインを保持し、キーやパスワードが JayV を経由することはありません。システムページでは、各エージェントがインストールされて応答しているかを確認できます。"$json$::jsonb),
  ('ja', 'docs.answerRecall.title', $json$"過去の回答"$json$::jsonb),
  ('ja', 'docs.answerRecall.summary', $json$"同じプロジェクトの別のチャットで答えた依頼とほぼ同じ依頼は、すべてを調べ直す代わりにその回答から始めます。"$json$::jsonb),
  ('ja', 'docs.answerRecall.usage', $json$"プランに含まれていれば自動で動作します。過去の回答が再利用されるたびに、Jev パネルに表示されます。"$json$::jsonb),
  ('ja', 'docs.chatSearch.title', $json$"チャット検索"$json$::jsonb),
  ('ja', 'docs.chatSearch.summary', $json$"プロジェクトのすべての会話から単語を検索し、該当箇所をハイライトします。"$json$::jsonb),
  ('ja', 'docs.chatSearch.usage', $json$"プロジェクトのチャット画面で検索欄に入力します。インデックスはあなたのコンピューターにあり、検索がネットワークに出ることはありません。"$json$::jsonb),
  ('ja', 'docs.cli.title', $json$"ターミナルでの JayV"$json$::jsonb),
  ('ja', 'docs.cli.summary', $json$"同じオーケストレーターが、アプリで設定したエージェントとモデルを使ってターミナルから動きます。"$json$::jsonb),
  ('ja', 'docs.cli.usage', $json$"プロジェクトのフォルダーで jayv に続けてコマンドを実行するか、--root でフォルダーを指定します。--config で別の設定ファイルを指定できます。"$json$::jsonb),
  ('ja', 'docs.commandPalette.title', $json$"コマンドパレットとショートカット"$json$::jsonb),
  ('ja', 'docs.commandPalette.summary', $json$"ボタンのある操作はすべてコマンドパレットにも名前があり、主要な画面にはキーボードショートカットがあります。"$json$::jsonb),
  ('ja', 'docs.commandPalette.usage', $json$"どの画面でも Ctrl+K（Mac では ⌘K）を押して入力します。ページへの移動、プロジェクト・チャット・組織を開く、チャットの開始、テーマの切り替えができます。"$json$::jsonb),
  ('ja', 'docs.contextCache.title', $json$"コンテキストキャッシュ"$json$::jsonb),
  ('ja', 'docs.contextCache.summary', $json$"依頼のために組み立てたコンテキストは、ファイルが変わらないあいだ少なくとも 5 分間再利用されるため、続く依頼でプロジェクトを再検索しません。"$json$::jsonb),
  ('ja', 'docs.contextCache.usage', $json$"常に有効です。プロジェクトのファイルを変更すると、変わった部分だけが更新されます。"$json$::jsonb),
  ('ja', 'docs.entryGate.title', $json$"入口ゲート"$json$::jsonb),
  ('ja', 'docs.entryGate.summary', $json$"Jev は、エージェントが動く前にすべての依頼を確認します。何を求めているか、どこに適用されるか、何が足りないかを見ます。"$json$::jsonb),
  ('ja', 'docs.entryGate.usage', $json$"常に有効です。足りないものがあるとゲートが表示し、そのまま送信する、JayV が書き直した版を送信する、依頼を補足する、のいずれかを選べます。"$json$::jsonb),
  ('ja', 'docs.exitGate.title', $json$"出口ゲート"$json$::jsonb),
  ('ja', 'docs.exitGate.summary', $json$"Jev は、あなたが回答に基づいて動く前に、各回答のコマンドとファイルをプロジェクトのルールと照合します。"$json$::jsonb),
  ('ja', 'docs.exitGate.usage', $json$"常に有効です。保護されたファイルに触れる回答や禁止されたコマンドを実行する回答は保留され、ゲートが理由を説明します。"$json$::jsonb),
  ('ja', 'docs.gateBoard.title', $json$"ゲートボード"$json$::jsonb),
  ('ja', 'docs.gateBoard.summary', $json$"プロジェクトで Jev が通した依頼、確認した依頼、止めた依頼をすべてまとめた 1 ページです。"$json$::jsonb),
  ('ja', 'docs.gateBoard.usage', $json$"サイドメニュー、ステータスバーの件数、または Ctrl+G（Mac では ⌘G）で開きます。ゲートへの回答はプロジェクトのメモになり、同じことは再び聞かれません。"$json$::jsonb),
  ('ja', 'docs.leanCode.title', $json$"簡潔なコード"$json$::jsonb),
  ('ja', 'docs.leanCode.summary', $json$"開発モードでは、エージェントはタスクを解決する最小限のコードを書き、言語・プラットフォーム・インストール済みライブラリの機能を再利用します。"$json$::jsonb),
  ('ja', 'docs.leanCode.usage', $json$"既定で有効です。入力検証、エラー処理、セキュリティ、アクセシビリティは削られません。プロフィールページの「あなたのレベル」でオフにできます。"$json$::jsonb),
  ('ja', 'docs.liveFiles.title', $json$"ライブファイル"$json$::jsonb),
  ('ja', 'docs.liveFiles.summary', $json$"会話の横のパネルに、依頼で変更されるファイルが新しい順に表示され、エージェントが書くあいだ各ファイルの差分を確認できます。"$json$::jsonb),
  ('ja', 'docs.liveFiles.usage', $json$"チャットのヘッダーで「ライブ」をクリックします。最初の変更時にも自動で開きます。エージェントを追いかけると、各ファイルが変わった瞬間に表示されます。"$json$::jsonb),
  ('ja', 'docs.orgChat.title', $json$"組織チャット"$json$::jsonb),
  ('ja', 'docs.orgChat.summary', $json$"組織のすべてのリポジトリを一度に扱うチャットです。エージェント、インデックス、ゲートがそのすべてを参照します。"$json$::jsonb),
  ('ja', 'docs.orgChat.usage', $json$"組織のページで「組織チャット」をクリックします。このコンピューターに組織のフォルダーがない場合は、先にフォルダーの指定を求められます。"$json$::jsonb),
  ('ja', 'docs.organizations.title', $json$"組織"$json$::jsonb),
  ('ja', 'docs.organizations.summary', $json$"組織は、メンバー、リポジトリ、チーム全体が従う LLM ポリシーをまとめます。"$json$::jsonb),
  ('ja', 'docs.organizations.usage', $json$"JayV サイトのダッシュボードで組織を作成し、メンバーを招待します。アプリでは Ctrl+2（Mac では ⌘2）で組織とそのリポジトリを開けます。"$json$::jsonb),
  ('ja', 'docs.parallelRequests.title', $json$"依頼の並行実行"$json$::jsonb),
  ('ja', 'docs.parallelRequests.summary', $json$"プランで同時に複数の依頼が許可されている場合、別々のプロジェクトのチャットは同時に実行され、それぞれが専用のエージェントとインデックスを使います。"$json$::jsonb),
  ('ja', 'docs.parallelRequests.usage', $json$"設定は不要です。別々のプロジェクトのチャットで依頼を送れば、互いを待ちません。同じプロジェクトの依頼は引き続き 1 件ずつ処理され、2 つのエージェントが同じフォルダーに書き込むことはありません。"$json$::jsonb),
  ('ja', 'docs.parallelTasks.title', $json$"並行エージェント"$json$::jsonb),
  ('ja', 'docs.parallelTasks.summary', $json$"git プロジェクトの大きな開発依頼は、別々のファイルを扱う最大 4 つの部分に分けられ、それぞれ別のエージェントがプロジェクトの専用コピーで作業します。"$json$::jsonb),
  ('ja', 'docs.parallelTasks.usage', $json$"設定 › Jev › ルーティングで「大きな依頼をエージェントで分担」をオンにします。各部分は git worktree で同時に動き、変更はあなたのフォルダーに戻ります。"$json$::jsonb),
  ('ja', 'docs.planFirst.title', $json$"構築の前に計画"$json$::jsonb),
  ('ja', 'docs.planFirst.summary', $json$"複雑な開発依頼では、最も強力な推論モデルが先に計画を書き、構築を担当するエージェントは依頼とあわせてその計画を受け取ります。"$json$::jsonb),
  ('ja', 'docs.planFirst.usage', $json$"設定 › Jev › ルーティングで「あるモデルで計画し、別のモデルで構築」をオンにします。計画は書かれるそばから進行状況パネルに表示され、失敗した場合は開発が従来どおり進みます。"$json$::jsonb),
  ('ja', 'docs.profilePhoto.title', $json$"プロフィール写真"$json$::jsonb),
  ('ja', 'docs.profilePhoto.summary', $json$"メールアドレスとパスワード、連携アカウントのどの方法でサインインしても JayV に表示される、あなた自身の写真です。"$json$::jsonb),
  ('ja', 'docs.profilePhoto.usage', $json$"JayV サイトでダッシュボード › アカウントを開き、写真をクリックして画像を選び、切り抜きを調整します。アプリには次回の起動時に表示されます。削除すると、連携アカウントの写真に戻ります。"$json$::jsonb),
  ('ja', 'docs.progressPanel.title', $json$"進行状況パネル"$json$::jsonb),
  ('ja', 'docs.progressPanel.summary', $json$"サイドメニューの横のパネルに、JayV がいま行っていることが 1 行に 1 ステップずつ表示され、会話は画面の幅いっぱいに使えます。"$json$::jsonb),
  ('ja', 'docs.progressPanel.usage', $json$"依頼の実行中は自動で開きます。不要なときは細い帯に折りたためます。組織チャットではリポジトリの一覧も表示されます。"$json$::jsonb),
  ('ja', 'docs.projectNotes.title', $json$"プロジェクトメモリー"$json$::jsonb),
  ('ja', 'docs.projectNotes.summary', $json$"テスト方法、ファイルの場所、触ってはいけないものなど、プロジェクトについての短いメモです。エージェントは各セッションの最初に一度だけ受け取ります。"$json$::jsonb),
  ('ja', 'docs.projectNotes.usage', $json$"プロジェクトのチャット画面で「プロジェクトメモリー」をクリックし、2,200 文字まで書きます。秘密情報は受け付けられず、メモはアカウントと同期されます。"$json$::jsonb),
  ('ja', 'docs.secondOpinion.title', $json$"セカンドオピニオン"$json$::jsonb),
  ('ja', 'docs.secondOpinion.summary', $json$"依頼が開発モードでプロジェクトを変更した後、別のプロバイダーのエージェントが何も編集せずに差分を読み、見つけた問題を列挙します。"$json$::jsonb),
  ('ja', 'docs.secondOpinion.usage', $json$"設定 › Jev › ルーティングで「別のエージェントによるセカンドオピニオン」をオンにします。2 つ以上のエージェントを有効にする必要があります。回答が先に届き、レビューは別のメッセージで続きます。"$json$::jsonb),
  ('ja', 'docs.secretRedaction.title', $json$"秘密情報の伏せ字化"$json$::jsonb),
  ('ja', 'docs.secretRedaction.summary', $json$"キー、トークン、パスワードは、ファイルがモデルに届く前に置き換えられます。"$json$::jsonb),
  ('ja', 'docs.secretRedaction.usage', $json$"すべてのプランで常に有効で、オフにするスイッチはありません。"$json$::jsonb),
  ('ja', 'docs.sensitiveFiles.title', $json$"保護されたファイル"$json$::jsonb),
  ('ja', 'docs.sensitiveFiles.summary', $json$".env、秘密鍵、証明書などのファイルはコンテキストに入らず、エージェントは読み取りも編集もできません。"$json$::jsonb),
  ('ja', 'docs.sensitiveFiles.usage', $json$"既定のリストは常に適用されます。設定 › アプリの「読み取らない」に独自のパターンを追加できます。Claude Code はこれらのファイルの読み取りと編集も自らブロックし、エージェントが保護されたファイルを変更すると出口ゲートで保留されます。"$json$::jsonb),
  ('ja', 'docs.stats.title', $json$"統計"$json$::jsonb),
  ('ja', 'docs.stats.summary', $json$"プロジェクトごと・組織ごとのトークン使用量、コスト、エージェントの利用枠、グラフ。"$json$::jsonb),
  ('ja', 'docs.stats.usage', $json$"サイドメニューから統計を開くか、Ctrl+3（Mac では ⌘3）を押します。"$json$::jsonb),
  ('ja', 'docs.stopRequest.title', $json$"依頼の停止"$json$::jsonb),
  ('ja', 'docs.stopRequest.summary', $json$"実行中の依頼はいつでも止められます。エージェントとそれが開いたすべてのプロセスが終了し、それまでの発言はチャットに残ります。"$json$::jsonb),
  ('ja', 'docs.stopRequest.usage', $json$"依頼の実行中は送信ボタンが停止ボタンに変わります。キューで待っている依頼はキューから外せます。すべての依頼は設定 › Jev で決めた制限時間（既定は 30 分）でも停止します。"$json$::jsonb),
  ('ja', 'docs.symbolIndex.title', $json$"Claude 向けシンボルインデックス"$json$::jsonb),
  ('ja', 'docs.symbolIndex.summary', $json$"JayV は、関数・型・クラスが定義されている場所をあなたのコンピューター上でトークンを使わずに記録し、Claude Code はフォルダーを走査する代わりにその地図に問い合わせられます。"$json$::jsonb),
  ('ja', 'docs.symbolIndex.usage', $json$"プランに含まれている場合、設定の Claude Code のオプションで「JayV シンボルツール」をオンにします。同じインデックスは jayv mcp コマンドで任意のエージェントに提供されます。"$json$::jsonb),
  ('ja', 'docs.twoFactor.title', $json$"二要素認証"$json$::jsonb),
  ('ja', 'docs.twoFactor.summary', $json$"パスワードや連携アカウントに加えて、サインイン時にスマートフォンの認証アプリのコードを求めます。"$json$::jsonb),
  ('ja', 'docs.twoFactor.usage', $json$"JayV サイトでダッシュボード › アカウント › セキュリティを開き、認証アプリで QR コードを読み取り、最初のコードで確定します。"$json$::jsonb),
  ('ja', 'docs.updates.title', $json$"アップデートと新機能"$json$::jsonb),
  ('ja', 'docs.updates.summary', $json$"JayV はバックグラウンドで新しいバージョンを確認し、アップデートのたびに最後に見たバージョンからの変更点を表示します。"$json$::jsonb),
  ('ja', 'docs.updates.usage', $json$"新しいバージョンが出ると、バーに「変更内容」と「今すぐ更新」が表示されます。全履歴はコマンドパレットの「JayV の新機能」と、サイトのリリースノートページで確認できます。"$json$::jsonb),
  ('ja', 'docs.workModes.title', $json$"作業モード：自動・計画・開発"$json$::jsonb),
  ('ja', 'docs.workModes.summary', $json$"チャットごとに作業モードがあります。計画はプロジェクトを読むだけで計画を返し、開発はファイルを変更し、自動は依頼ごとに Jev が選びます。"$json$::jsonb),
  ('ja', 'docs.workModes.usage', $json$"メッセージ欄の下でモードを選ぶか、メッセージの先頭に /plan、/build、/auto と入力するか、Ctrl+.（Mac では ⌘.）を押します。計画モードのチャットで実装を頼むと、Jev が開発モードに切り替えます。"$json$::jsonb),
  ('ja', 'docs.command.modeAuto', $json$"このチャットの依頼ごとに、Jev が計画か開発かを選びます。"$json$::jsonb),
  ('ja', 'docs.command.modePlan', $json$"チャットを計画モードにします。エージェントは読むだけで計画を返します。コマンドの後のテキストは依頼として送られます。"$json$::jsonb),
  ('ja', 'docs.command.modeBuild', $json$"チャットを開発モードにします。エージェントはプロジェクトのファイルを変更します。コマンドの後のテキストは依頼として送られます。"$json$::jsonb),
  ('ja', 'docs.command.palette', $json$"コマンドパレットを開きます。"$json$::jsonb),
  ('ja', 'docs.command.projects', $json$"プロジェクトに移動します。"$json$::jsonb),
  ('ja', 'docs.command.organizations', $json$"組織に移動します。"$json$::jsonb),
  ('ja', 'docs.command.stats', $json$"統計に移動します。"$json$::jsonb),
  ('ja', 'docs.command.system', $json$"システムに移動します。"$json$::jsonb),
  ('ja', 'docs.command.settings', $json$"設定を開きます。"$json$::jsonb),
  ('ja', 'docs.command.newChat', $json$"開いているプロジェクトで新しいチャットを始めます。"$json$::jsonb),
  ('ja', 'docs.command.gate', $json$"開いているプロジェクトのゲートを開きます。"$json$::jsonb),
  ('ja', 'docs.command.workMode', $json$"開いているチャットの作業モードを切り替えます。"$json$::jsonb),
  ('ja', 'docs.command.cliStatus', $json$"バージョン、設定ファイル、実行できるエージェントとモデルの数、インデックス済みのファイル数を表示します。"$json$::jsonb),
  ('ja', 'docs.command.cliRun', $json$"依頼を 1 件、ゲートとルーターを通して送り、回答を出力します。"$json$::jsonb),
  ('ja', 'docs.command.cliIndex', $json$"プロジェクトのフォルダーをインデックス化し、取り込んだファイル数を出力します。"$json$::jsonb),
  ('ja', 'docs.command.cliVersion', $json$"インストールされているバージョンを出力します。"$json$::jsonb),
  ('ja', 'docs.command.cliBench', $json$"タスクファイルを JayV 経由とエージェント単体でそれぞれ専用のコピーで実行し、ラウンド数とコストを比較します。"$json$::jsonb),
  ('ja', 'docs.command.cliMcp', $json$"プロジェクトのシンボルインデックスを MCP（stdio）でコーディングエージェントに提供します。"$json$::jsonb),
  ('de', 'docs.adaptiveRouting.title', $json$"Adaptives Routing"$json$::jsonb),
  ('de', 'docs.adaptiveRouting.summary', $json$"Jev wählt, welcher Agent und welches Modell jede Anfrage beantworten, und berücksichtigt dabei die Bilanz jedes Modells pro Anfrageart."$json$::jsonb),
  ('de', 'docs.adaptiveRouting.usage', $json$"Lass in den Einstellungen mehr als einen Agenten eingeschaltet. Eine Antwort, die du als nicht funktionierend meldest oder die die Ausgangspforte zurückhält, kostet das Modell einen Punkt. Fehlt der gewählte Agent oder ist er nicht angemeldet, geht die Anfrage an den nächsten."$json$::jsonb),
  ('de', 'docs.agentSessions.title', $json$"Agenten-Sitzungen"$json$::jsonb),
  ('de', 'docs.agentSessions.summary', $json$"Jeder Chat setzt die Sitzung seines Agenten fort, statt bei jeder Nachricht das Projekt und das ganze Gespräch neu zu lesen."$json$::jsonb),
  ('de', 'docs.agentSessions.usage', $json$"Immer aktiv. Eine neue Sitzung beginnt nach 10 Anfragen oder wenn sich Agent, Modell oder Ordner ändern."$json$::jsonb),
  ('de', 'docs.agents.title', $json$"Kommandozeilen-Agenten"$json$::jsonb),
  ('de', 'docs.agents.summary', $json$"JayV schreibt selbst keinen Code: Es orchestriert die Coding-Agenten, die du schon nutzt — Codex, Claude Code, GitHub Copilot und Cursor Agent — und startet dafür die Kommandozeile jedes Agenten auf deinem Computer."$json$::jsonb),
  ('de', 'docs.agents.usage', $json$"Öffne die Einstellungen, schalte die auf diesem Computer installierten Agenten ein und liste die Modelle auf, die jeder nutzen darf. Jede CLI behält ihre eigene Anmeldung; kein Schlüssel und kein Passwort laufen über JayV. Die Seite System zeigt, ob jeder Agent installiert ist und antwortet."$json$::jsonb),
  ('de', 'docs.answerRecall.title', $json$"Frühere Antworten"$json$::jsonb),
  ('de', 'docs.answerRecall.summary', $json$"Eine Anfrage, die fast genauso schon in einem anderen Chat desselben Projekts beantwortet wurde, startet von dieser Antwort, statt alles neu zu erkunden."$json$::jsonb),
  ('de', 'docs.answerRecall.usage', $json$"Funktioniert von selbst, wenn dein Tarif es enthält. Jedes Mal, wenn eine frühere Antwort wiederverwendet wird, zeigt das Jev-Panel es an."$json$::jsonb),
  ('de', 'docs.chatSearch.title', $json$"Chat-Suche"$json$::jsonb),
  ('de', 'docs.chatSearch.summary', $json$"Suche nach Wörtern in allen Gesprächen eines Projekts, mit hervorgehobener Fundstelle."$json$::jsonb),
  ('de', 'docs.chatSearch.usage', $json$"Tippe auf dem Chat-Bildschirm eines Projekts in das Suchfeld. Der Index liegt auf deinem Computer, und die Suche geht nie ins Netz."$json$::jsonb),
  ('de', 'docs.cli.title', $json$"JayV im Terminal"$json$::jsonb),
  ('de', 'docs.cli.summary', $json$"Derselbe Orchestrator läuft im Terminal, mit den Agenten und Modellen, die in der App eingerichtet sind."$json$::jsonb),
  ('de', 'docs.cli.usage', $json$"Führe jayv mit einem Befehl im Projektordner aus oder gib den Ordner mit --root an. --config verweist auf eine andere Konfigurationsdatei."$json$::jsonb),
  ('de', 'docs.commandPalette.title', $json$"Befehlspalette und Tastenkürzel"$json$::jsonb),
  ('de', 'docs.commandPalette.summary', $json$"Alles, was einen Button hat, hat auch einen Namen in der Befehlspalette, und die Hauptbildschirme haben Tastenkürzel."$json$::jsonb),
  ('de', 'docs.commandPalette.usage', $json$"Drücke auf jedem Bildschirm Strg+K (⌘K auf dem Mac) und tippe: zu einer Seite gehen, ein Projekt, einen Chat oder eine Organisation öffnen, einen Chat starten oder das Design wechseln."$json$::jsonb),
  ('de', 'docs.contextCache.title', $json$"Kontext-Cache"$json$::jsonb),
  ('de', 'docs.contextCache.summary', $json$"Der für eine Anfrage aufgebaute Kontext wird mindestens fünf Minuten wiederverwendet, solange die Dateien gleich bleiben, sodass eine Folgeanfrage das Projekt nicht erneut durchsucht."$json$::jsonb),
  ('de', 'docs.contextCache.usage', $json$"Immer aktiv. Ändert sich eine Datei im Projekt, wird nur das Geänderte aktualisiert."$json$::jsonb),
  ('de', 'docs.entryGate.title', $json$"Eingangspforte"$json$::jsonb),
  ('de', 'docs.entryGate.summary', $json$"Jev prüft jede Anfrage, bevor ein Agent startet: was sie verlangt, wo sie gilt und was fehlt."$json$::jsonb),
  ('de', 'docs.entryGate.usage', $json$"Immer aktiv. Wenn etwas fehlt, zeigt die Pforte es an und bietet an, die Anfrage so zu senden, die von JayV umgeschriebene Fassung zu senden oder die Anfrage zu ergänzen."$json$::jsonb),
  ('de', 'docs.exitGate.title', $json$"Ausgangspforte"$json$::jsonb),
  ('de', 'docs.exitGate.summary', $json$"Jev prüft die Befehle und Dateien jeder Antwort gegen die Regeln des Projekts, bevor du darauf reagierst."$json$::jsonb),
  ('de', 'docs.exitGate.usage', $json$"Immer aktiv. Eine Antwort, die eine geschützte Datei berührt oder einen verbotenen Befehl ausführt, wird zurückgehalten, und die Pforte erklärt warum."$json$::jsonb),
  ('de', 'docs.gateBoard.title', $json$"Pfortenübersicht"$json$::jsonb),
  ('de', 'docs.gateBoard.summary', $json$"Eine Seite mit allem, was Jev im Projekt durchgelassen, nachgefragt oder blockiert hat."$json$::jsonb),
  ('de', 'docs.gateBoard.usage', $json$"Öffne sie über das Seitenmenü, über den Zähler in der Statusleiste oder mit Strg+G (⌘G auf dem Mac). Antworten, die du der Pforte gibst, werden zu Projektnotizen, und sie fragt nicht noch einmal."$json$::jsonb),
  ('de', 'docs.leanCode.title', $json$"Schlanker Code"$json$::jsonb),
  ('de', 'docs.leanCode.summary', $json$"Im Entwicklungsmodus schreibt der Agent den kleinstmöglichen Code, der die Aufgabe löst, und nutzt, was Sprache, Plattform oder eine installierte Bibliothek schon können."$json$::jsonb),
  ('de', 'docs.leanCode.usage', $json$"Standardmäßig an. Validierung, Fehlerbehandlung, Sicherheit und Barrierefreiheit werden nie gekürzt. Abschalten unter Ihr Level auf der Seite Profil."$json$::jsonb),
  ('de', 'docs.liveFiles.title', $json$"Live-Dateien"$json$::jsonb),
  ('de', 'docs.liveFiles.summary', $json$"Ein Panel neben dem Gespräch zeigt jede Datei, die die Anfrage ändert, die neueste zuerst, mit dem Diff jeder Datei, während der Agent schreibt."$json$::jsonb),
  ('de', 'docs.liveFiles.usage', $json$"Klicke im Chat-Kopf auf Live; das Panel öffnet sich auch von selbst bei der ersten Änderung. Folge dem Agenten, um jede Datei zu sehen, sobald sie sich ändert."$json$::jsonb),
  ('de', 'docs.orgChat.title', $json$"Organisations-Chat"$json$::jsonb),
  ('de', 'docs.orgChat.summary', $json$"Ein Chat, der an allen Repositorys einer Organisation gleichzeitig arbeitet, wobei Agent, Index und Pforte alle sehen."$json$::jsonb),
  ('de', 'docs.orgChat.usage', $json$"Klicke auf der Seite der Organisation auf Organisations-Chat. Ohne einen Organisationsordner auf diesem Computer fragt JayV zuerst nach einem."$json$::jsonb),
  ('de', 'docs.organizations.title', $json$"Organisationen"$json$::jsonb),
  ('de', 'docs.organizations.summary', $json$"Organisationen bündeln Personen, Repositorys und die LLM-Richtlinie, der das ganze Team folgt."$json$::jsonb),
  ('de', 'docs.organizations.usage', $json$"Erstelle eine Organisation und lade Mitglieder im Dashboard der JayV-Website ein. In der App öffnet Strg+2 (⌘2 auf dem Mac) deine Organisationen und ihre Repositorys."$json$::jsonb),
  ('de', 'docs.parallelRequests.title', $json$"Anfragen parallel"$json$::jsonb),
  ('de', 'docs.parallelRequests.summary', $json$"Wenn dein Tarif mehr als eine Anfrage gleichzeitig erlaubt, laufen Chats aus verschiedenen Projekten gleichzeitig, jeder mit eigenen Agenten und eigenem Index."$json$::jsonb),
  ('de', 'docs.parallelRequests.usage', $json$"Nichts einzuschalten: Sende Anfragen in Chats verschiedener Projekte, und sie warten nicht mehr aufeinander. Anfragen aus demselben Projekt laufen weiterhin nacheinander, damit nie zwei Agenten in denselben Ordner schreiben."$json$::jsonb),
  ('de', 'docs.parallelTasks.title', $json$"Parallele Agenten"$json$::jsonb),
  ('de', 'docs.parallelTasks.summary', $json$"Eine große Entwicklungsanfrage in einem Git-Projekt wird in bis zu vier Teile mit getrennten Dateien aufgeteilt, jeder von einem anderen Agenten in einer eigenen Kopie des Projekts erledigt."$json$::jsonb),
  ('de', 'docs.parallelTasks.usage', $json$"Schalte Große Anfragen auf Agenten verteilen unter Einstellungen › Jev › Routing ein. Die Teile laufen gleichzeitig in Git-Worktrees, und die Änderungen kommen in deinen Ordner zurück."$json$::jsonb),
  ('de', 'docs.planFirst.title', $json$"Erst planen, dann bauen"$json$::jsonb),
  ('de', 'docs.planFirst.summary', $json$"Bei einer komplexen Entwicklungsanfrage schreibt dein stärkstes Reasoning-Modell zuerst einen Plan, und der zum Bauen gewählte Agent bekommt ihn mit der Anfrage."$json$::jsonb),
  ('de', 'docs.planFirst.usage', $json$"Schalte Mit einem Modell planen, mit einem anderen bauen unter Einstellungen › Jev › Routing ein. Der Plan erscheint im Fortschrittspanel, während er geschrieben wird; schlägt er fehl, läuft die Entwicklung wie bisher weiter."$json$::jsonb),
  ('de', 'docs.profilePhoto.title', $json$"Profilfoto"$json$::jsonb),
  ('de', 'docs.profilePhoto.summary', $json$"Dein eigenes Foto, das JayV zeigt, egal wie du dich anmeldest — mit E-Mail und Passwort oder mit einem verknüpften Konto."$json$::jsonb),
  ('de', 'docs.profilePhoto.usage', $json$"Öffne auf der JayV-Website Dashboard › Konto, klicke auf das Foto, wähle ein Bild und passe den Ausschnitt an. Die App zeigt es beim nächsten Start; entfernst du es, kommt das Foto deines verknüpften Kontos zurück."$json$::jsonb),
  ('de', 'docs.progressPanel.title', $json$"Fortschrittspanel"$json$::jsonb),
  ('de', 'docs.progressPanel.summary', $json$"Ein Panel neben dem Seitenmenü zeigt, was JayV gerade tut, ein Schritt pro Zeile, damit das Gespräch die volle Breite behält."$json$::jsonb),
  ('de', 'docs.progressPanel.usage', $json$"Das Panel öffnet sich von selbst, während eine Anfrage läuft. Klappe es zu einem schmalen Streifen ein, wenn du es nicht brauchst; in einem Organisations-Chat listet es auch die Repositorys."$json$::jsonb),
  ('de', 'docs.projectNotes.title', $json$"Projektgedächtnis"$json$::jsonb),
  ('de', 'docs.projectNotes.summary', $json$"Kurze Notizen zum Projekt — wie man testet, wo was liegt, was man nicht anfassen soll —, die der Agent einmal zu Beginn jeder Sitzung bekommt."$json$::jsonb),
  ('de', 'docs.projectNotes.usage', $json$"Klicke auf dem Chat-Bildschirm eines Projekts auf Projektgedächtnis und schreibe bis zu 2.200 Zeichen. Geheimnisse werden abgelehnt, und die Notizen werden mit deinem Konto synchronisiert."$json$::jsonb),
  ('de', 'docs.secondOpinion.title', $json$"Zweite Meinung"$json$::jsonb),
  ('de', 'docs.secondOpinion.summary', $json$"Nachdem eine Anfrage das Projekt im Entwicklungsmodus geändert hat, liest ein Agent eines anderen Anbieters den Diff, ohne etwas zu bearbeiten, und listet die gefundenen Probleme auf."$json$::jsonb),
  ('de', 'docs.secondOpinion.usage', $json$"Schalte Zweite Meinung von einem anderen Agenten unter Einstellungen › Jev › Routing ein. Es braucht mindestens zwei eingeschaltete Agenten; die Antwort kommt zuerst, die Prüfung folgt in einer eigenen Nachricht."$json$::jsonb),
  ('de', 'docs.secretRedaction.title', $json$"Schwärzen von Geheimnissen"$json$::jsonb),
  ('de', 'docs.secretRedaction.summary', $json$"Schlüssel, Tokens und Passwörter werden ersetzt, bevor eine Datei ein Modell erreicht."$json$::jsonb),
  ('de', 'docs.secretRedaction.usage', $json$"In jedem Tarif immer aktiv; es gibt keinen Schalter zum Abschalten."$json$::jsonb),
  ('de', 'docs.sensitiveFiles.title', $json$"Geschützte Dateien"$json$::jsonb),
  ('de', 'docs.sensitiveFiles.summary', $json$"Dateien wie .env, private Schlüssel und Zertifikate gelangen nie in den Kontext, und Agenten können sie weder lesen noch bearbeiten."$json$::jsonb),
  ('de', 'docs.sensitiveFiles.usage', $json$"Die Standardliste gilt immer; ergänze eigene Muster unter Nie lesen in Einstellungen › App. Claude Code blockiert außerdem eigene Lese- und Schreibzugriffe auf diese Dateien, und jede Änderung eines Agenten an einer geschützten Datei wird an der Ausgangspforte zurückgehalten."$json$::jsonb),
  ('de', 'docs.stats.title', $json$"Statistiken"$json$::jsonb),
  ('de', 'docs.stats.summary', $json$"Token-Verbrauch, Kosten, Agenten-Kontingente und Diagramme pro Projekt und pro Organisation."$json$::jsonb),
  ('de', 'docs.stats.usage', $json$"Öffne Statistiken über das Seitenmenü oder drücke Strg+3 (⌘3 auf dem Mac)."$json$::jsonb),
  ('de', 'docs.stopRequest.title', $json$"Eine Anfrage stoppen"$json$::jsonb),
  ('de', 'docs.stopRequest.summary', $json$"Eine laufende Anfrage lässt sich jederzeit stoppen: Der Agent und alle Prozesse, die er geöffnet hat, werden beendet, und was er schon gesagt hat, bleibt im Chat."$json$::jsonb),
  ('de', 'docs.stopRequest.usage', $json$"Während eine Anfrage läuft, wird aus dem Button Senden ein Stoppen. Eine Anfrage, die in der Warteschlange wartet, lässt sich daraus entfernen. Jede Anfrage stoppt außerdem am Zeitlimit aus Einstellungen › Jev (standardmäßig 30 Minuten)."$json$::jsonb),
  ('de', 'docs.symbolIndex.title', $json$"Symbolindex für Claude"$json$::jsonb),
  ('de', 'docs.symbolIndex.summary', $json$"JayV erfasst, wo jede Funktion, jeder Typ und jede Klasse definiert ist, auf deinem Computer und ohne Tokens zu verbrauchen, und Claude Code kann diese Karte abfragen, statt den Ordner zu durchsuchen."$json$::jsonb),
  ('de', 'docs.symbolIndex.usage', $json$"Schalte JayV-Symbolwerkzeuge in den Claude-Code-Optionen in den Einstellungen ein, wenn dein Tarif es enthält. Derselbe Index steht jedem Agenten über den Befehl jayv mcp zur Verfügung."$json$::jsonb),
  ('de', 'docs.twoFactor.title', $json$"Zwei-Faktor-Authentifizierung"$json$::jsonb),
  ('de', 'docs.twoFactor.summary', $json$"Neben dem Passwort oder dem verknüpften Konto verlangt die Anmeldung einen Code aus einer Authenticator-App auf deinem Smartphone."$json$::jsonb),
  ('de', 'docs.twoFactor.usage', $json$"Öffne auf der JayV-Website Dashboard › Konto › Sicherheit, scanne den QR-Code mit einer Authenticator-App und bestätige mit dem ersten Code."$json$::jsonb),
  ('de', 'docs.updates.title', $json$"Updates und Neuigkeiten"$json$::jsonb),
  ('de', 'docs.updates.summary', $json$"JayV sucht im Hintergrund nach einer neuen Version und zeigt nach jedem Update, was sich seit der letzten gesehenen Version geändert hat."$json$::jsonb),
  ('de', 'docs.updates.usage', $json$"Wenn eine neue Version erscheint, bietet eine Leiste Was sich ändert und Jetzt aktualisieren an. Den vollständigen Verlauf findest du unter Neu in JayV in der Befehlspalette und auf der Seite Versionshinweise der Website."$json$::jsonb),
  ('de', 'docs.workModes.title', $json$"Arbeitsmodi: Auto, Planung und Entwicklung"$json$::jsonb),
  ('de', 'docs.workModes.summary', $json$"Jeder Chat hat einen Arbeitsmodus. Planung liest nur das Projekt und antwortet mit einem Plan; Entwicklung ändert Dateien; Auto lässt Jev bei jeder Anfrage wählen."$json$::jsonb),
  ('de', 'docs.workModes.usage', $json$"Wähle den Modus unter dem Nachrichtenfeld, tippe /plan, /build oder /auto am Anfang einer Nachricht oder drücke Strg+. (⌘. auf dem Mac). Wenn ein Chat in Planung um die Umsetzung bittet, wechselt Jev ihn in Entwicklung."$json$::jsonb),
  ('de', 'docs.command.modeAuto', $json$"Jev wählt für jede Anfrage in diesem Chat Planung oder Entwicklung."$json$::jsonb),
  ('de', 'docs.command.modePlan', $json$"Setzt den Chat auf Planung: Der Agent liest nur und antwortet mit einem Plan. Text nach dem Befehl wird als Anfrage gesendet."$json$::jsonb),
  ('de', 'docs.command.modeBuild', $json$"Setzt den Chat auf Entwicklung: Der Agent ändert Dateien im Projekt. Text nach dem Befehl wird als Anfrage gesendet."$json$::jsonb),
  ('de', 'docs.command.palette', $json$"Öffnet die Befehlspalette."$json$::jsonb),
  ('de', 'docs.command.projects', $json$"Geht zu Projekte."$json$::jsonb),
  ('de', 'docs.command.organizations', $json$"Geht zu Organisationen."$json$::jsonb),
  ('de', 'docs.command.stats', $json$"Geht zu Statistiken."$json$::jsonb),
  ('de', 'docs.command.system', $json$"Geht zu System."$json$::jsonb),
  ('de', 'docs.command.settings', $json$"Öffnet die Einstellungen."$json$::jsonb),
  ('de', 'docs.command.newChat', $json$"Startet einen neuen Chat im geöffneten Projekt."$json$::jsonb),
  ('de', 'docs.command.gate', $json$"Öffnet die Pforte des geöffneten Projekts."$json$::jsonb),
  ('de', 'docs.command.workMode', $json$"Wechselt den Arbeitsmodus des geöffneten Chats."$json$::jsonb),
